window.LWA_DATA={"mockHtml":"","secHtml":"","ncert":true,"pdfs":{},"papers":[{"id":"n11icw01","year":11,"stage":"Indian Constitution at Work","short":"Ch 1. Constitution: Why and How?","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 1: Constitution: Why and How?","notif":"Indian Constitution at Work · Class 11","held":"Chapter 1","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-1-constitution-why-and-how-mcqs","blurb":"MCQs on Chapter 1 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 1 Constitution: Why and How?","nsub":"pol","nbook":"icw","nch":1,"pdf":"","kw":"NCERT Class 11 Polity Chapter 1 Constitution: Why and How?"},{"id":"n11icw02","year":11,"stage":"Indian Constitution at Work","short":"Ch 2. Rights in the Indian Constitution","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 2: Rights in the Indian Constitution","notif":"Indian Constitution at Work · Class 11","held":"Chapter 2","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-2-rights-in-the-indian-constitution-mcqs","blurb":"MCQs on Chapter 2 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 2 Rights in the Indian Constitution","nsub":"pol","nbook":"icw","nch":2,"pdf":"","kw":"NCERT Class 11 Polity Chapter 2 Rights in the Indian Constitution"},{"id":"n11icw03","year":11,"stage":"Indian Constitution at Work","short":"Ch 3. Election and Representation","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 3: Election and Representation","notif":"Indian Constitution at Work · Class 11","held":"Chapter 3","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-3-election-and-representation-mcqs","blurb":"MCQs on Chapter 3 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 3 Election and Representation","nsub":"pol","nbook":"icw","nch":3,"pdf":"","kw":"NCERT Class 11 Polity Chapter 3 Election and Representation"},{"id":"n11icw04","year":11,"stage":"Indian Constitution at Work","short":"Ch 4. Executive","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 4: Executive","notif":"Indian Constitution at Work · Class 11","held":"Chapter 4","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-4-executive-mcqs","blurb":"MCQs on Chapter 4 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 4 Executive","nsub":"pol","nbook":"icw","nch":4,"pdf":"","kw":"NCERT Class 11 Polity Chapter 4 Executive"},{"id":"n11icw05","year":11,"stage":"Indian Constitution at Work","short":"Ch 5. Legislature","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 5: Legislature","notif":"Indian Constitution at Work · Class 11","held":"Chapter 5","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-5-legislature-mcqs","blurb":"MCQs on Chapter 5 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 5 Legislature","nsub":"pol","nbook":"icw","nch":5,"pdf":"","kw":"NCERT Class 11 Polity Chapter 5 Legislature"},{"id":"n11icw06","year":11,"stage":"Indian Constitution at Work","short":"Ch 6. Judiciary","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 6: Judiciary","notif":"Indian Constitution at Work · Class 11","held":"Chapter 6","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-6-judiciary-mcqs","blurb":"MCQs on Chapter 6 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 6 Judiciary","nsub":"pol","nbook":"icw","nch":6,"pdf":"","kw":"NCERT Class 11 Polity Chapter 6 Judiciary"},{"id":"n11icw07","year":11,"stage":"Indian Constitution at Work","short":"Ch 7. Federalism","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 7: Federalism","notif":"Indian Constitution at Work · Class 11","held":"Chapter 7","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-7-federalism-mcqs","blurb":"MCQs on Chapter 7 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 7 Federalism","nsub":"pol","nbook":"icw","nch":7,"pdf":"","kw":"NCERT Class 11 Polity Chapter 7 Federalism"},{"id":"n11icw08","year":11,"stage":"Indian Constitution at Work","short":"Ch 8. Local Governments","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 8: Local Governments","notif":"Indian Constitution at Work · Class 11","held":"Chapter 8","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-8-local-governments-mcqs","blurb":"MCQs on Chapter 8 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 8 Local Governments","nsub":"pol","nbook":"icw","nch":8,"pdf":"","kw":"NCERT Class 11 Polity Chapter 8 Local Governments"},{"id":"n11icw09","year":11,"stage":"Indian Constitution at Work","short":"Ch 9. Constitution as a Living Document","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 9: Constitution as a Living Document","notif":"Indian Constitution at Work · Class 11","held":"Chapter 9","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-9-constitution-as-a-living-document-mcqs","blurb":"MCQs on Chapter 9 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 9 Constitution as a Living Document","nsub":"pol","nbook":"icw","nch":9,"pdf":"","kw":"NCERT Class 11 Polity Chapter 9 Constitution as a Living Document"},{"id":"n11icw10","year":11,"stage":"Indian Constitution at Work","short":"Ch 10. The Philosophy of the Constitution","title":"NCERT Class 11 Polity · Indian Constitution at Work · Chapter 10: The Philosophy of the Constitution","notif":"Indian Constitution at Work · Class 11","held":"Chapter 10","fmt":"mcq","slug":"ncert-class-11-polity-indian-constitution-at-work-chapter-10-the-philosophy-of-the-constitution-mcqs","blurb":"MCQs on Chapter 10 of the NCERT Class 11 Political Science (Polity) textbook Indian Constitution at Work, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 10 The Philosophy of the Constitution","nsub":"pol","nbook":"icw","nch":10,"pdf":"","kw":"NCERT Class 11 Polity Chapter 10 The Philosophy of the Constitution"},{"id":"n11pt01","year":11,"stage":"Political Theory","short":"Ch 1. Political Theory: An Introduction","title":"NCERT Class 11 Polity · Political Theory · Chapter 1: Political Theory: An Introduction","notif":"Political Theory · Class 11","held":"Chapter 1","fmt":"mcq","slug":"ncert-class-11-polity-political-theory-chapter-1-political-theory-an-introduction-mcqs","blurb":"MCQs on Chapter 1 of the NCERT Class 11 Political Science (Polity) textbook Political Theory, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 1 Political Theory: An Introduction","nsub":"pol","nbook":"pt","nch":1,"pdf":"","kw":"NCERT Class 11 Polity Chapter 1 Political Theory: An Introduction"},{"id":"n11pt02","year":11,"stage":"Political Theory","short":"Ch 2. Freedom","title":"NCERT Class 11 Polity · Political Theory · Chapter 2: Freedom","notif":"Political Theory · Class 11","held":"Chapter 2","fmt":"mcq","slug":"ncert-class-11-polity-political-theory-chapter-2-freedom-mcqs","blurb":"MCQs on Chapter 2 of the NCERT Class 11 Political Science (Polity) textbook Political Theory, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 2 Freedom","nsub":"pol","nbook":"pt","nch":2,"pdf":"","kw":"NCERT Class 11 Polity Chapter 2 Freedom"},{"id":"n11pt03","year":11,"stage":"Political Theory","short":"Ch 3. Equality","title":"NCERT Class 11 Polity · Political Theory · Chapter 3: Equality","notif":"Political Theory · Class 11","held":"Chapter 3","fmt":"mcq","slug":"ncert-class-11-polity-political-theory-chapter-3-equality-mcqs","blurb":"MCQs on Chapter 3 of the NCERT Class 11 Political Science (Polity) textbook Political Theory, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 3 Equality","nsub":"pol","nbook":"pt","nch":3,"pdf":"","kw":"NCERT Class 11 Polity Chapter 3 Equality"},{"id":"n11pt04","year":11,"stage":"Political Theory","short":"Ch 4. Social Justice","title":"NCERT Class 11 Polity · Political Theory · Chapter 4: Social Justice","notif":"Political Theory · Class 11","held":"Chapter 4","fmt":"mcq","slug":"ncert-class-11-polity-political-theory-chapter-4-social-justice-mcqs","blurb":"MCQs on Chapter 4 of the NCERT Class 11 Political Science (Polity) textbook Political Theory, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 4 Social Justice","nsub":"pol","nbook":"pt","nch":4,"pdf":"","kw":"NCERT Class 11 Polity Chapter 4 Social Justice"},{"id":"n11pt05","year":11,"stage":"Political Theory","short":"Ch 5. Rights","title":"NCERT Class 11 Polity · Political Theory · Chapter 5: Rights","notif":"Political Theory · Class 11","held":"Chapter 5","fmt":"mcq","slug":"ncert-class-11-polity-political-theory-chapter-5-rights-mcqs","blurb":"MCQs on Chapter 5 of the NCERT Class 11 Political Science (Polity) textbook Political Theory, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 5 Rights","nsub":"pol","nbook":"pt","nch":5,"pdf":"","kw":"NCERT Class 11 Polity Chapter 5 Rights"},{"id":"n11pt06","year":11,"stage":"Political Theory","short":"Ch 6. Citizenship","title":"NCERT Class 11 Polity · Political Theory · Chapter 6: Citizenship","notif":"Political Theory · Class 11","held":"Chapter 6","fmt":"mcq","slug":"ncert-class-11-polity-political-theory-chapter-6-citizenship-mcqs","blurb":"MCQs on Chapter 6 of the NCERT Class 11 Political Science (Polity) textbook Political Theory, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 6 Citizenship","nsub":"pol","nbook":"pt","nch":6,"pdf":"","kw":"NCERT Class 11 Polity Chapter 6 Citizenship"},{"id":"n11pt07","year":11,"stage":"Political Theory","short":"Ch 7. Nationalism","title":"NCERT Class 11 Polity · Political Theory · Chapter 7: Nationalism","notif":"Political Theory · Class 11","held":"Chapter 7","fmt":"mcq","slug":"ncert-class-11-polity-political-theory-chapter-7-nationalism-mcqs","blurb":"MCQs on Chapter 7 of the NCERT Class 11 Political Science (Polity) textbook Political Theory, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 7 Nationalism","nsub":"pol","nbook":"pt","nch":7,"pdf":"","kw":"NCERT Class 11 Polity Chapter 7 Nationalism"},{"id":"n11pt08","year":11,"stage":"Political Theory","short":"Ch 8. Secularism","title":"NCERT Class 11 Polity · Political Theory · Chapter 8: Secularism","notif":"Political Theory · Class 11","held":"Chapter 8","fmt":"mcq","slug":"ncert-class-11-polity-political-theory-chapter-8-secularism-mcqs","blurb":"MCQs on Chapter 8 of the NCERT Class 11 Political Science (Polity) textbook Political Theory, with answers and explanations.","count":20,"key":"Learn with Anil's answers","en_only":true,"kwname":"NCERT Class 11 Polity Chapter 8 Secularism","nsub":"pol","nbook":"pt","nch":8,"pdf":"","kw":"NCERT Class 11 Polity Chapter 8 Secularism"}],"subjects":[{"id":"pol","name":"Political Science (Polity)","slug":"polity","topics":["Indian Constitution at Work","Political Theory"]},{"id":"his","name":"History","slug":"history","topics":["Themes in World History"]},{"id":"geo","name":"Geography","slug":"geography","topics":["Fundamentals of Physical Geography","India: Physical Environment"]},{"id":"eco","name":"Economics","slug":"economics","topics":["Indian Economic Development","Statistics for Economics"]},{"id":"soc","name":"Sociology","slug":"sociology","topics":["Introducing Sociology","Understanding Society"]},{"id":"art","name":"Fine Arts (Indian Art & Culture)","slug":"fine-arts","topics":["An Introduction to Indian Art, Part I"]},{"id":"phy","name":"Physics","slug":"physics","topics":["Physics, Parts I & II"]},{"id":"chem","name":"Chemistry","slug":"chemistry","topics":["Chemistry, Parts I & II"]},{"id":"bio","name":"Biology","slug":"biology","topics":["Biology"]}],"questions":[{"id":"n11icw01-1","p":"n11icw01","n":1,"s":"pol","t":"Indian Constitution at Work","q":"According to the NCERT chapter, what is the first and most basic function of a constitution?","w":"The chapter begins with coordination and assurance: a constitution gives a society basic rules that everyone knows and trusts, so its members can live together. The other functions build on this.","o":["To list the fundamental duties of citizens","To set up an independent judiciary","To declare the country a republic","To provide a set of basic rules that allow minimal coordination among the members of a society"],"a":[3]},{"id":"n11icw01-2","p":"n11icw01","n":2,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following functions of a constitution:\n1. Specifying who has the power to make decisions in a society\n2. Setting limits on what a government can impose on its citizens\n3. Enabling the government to fulfil the aspirations of a society\n4. Expressing the fundamental identity of a people\nWhich of the above are discussed in the NCERT chapter as functions of a constitution?","w":"The chapter lists all four, along with providing basic rules for coordination: deciding who makes decisions, limiting government power, enabling a just society, and expressing a people's collective identity.","o":["1 and 2 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"a":[3]},{"id":"n11icw01-3","p":"n11icw01","n":3,"s":"pol","t":"Indian Constitution at Work","q":"The part of a constitution that decides how the government will be constituted and who can make laws relates to which function?","w":"Specifying decision-making powers is about who is allowed to make laws and how the government is formed. In India, for example, Parliament makes most laws and its members are chosen by the people.","o":["Specifying the decision-making powers in a society","Limiting the powers of the government","Expressing the identity of a people","Fulfilling the aspirations of a society"],"a":[0]},{"id":"n11icw01-4","p":"n11icw01","n":4,"s":"pol","t":"Indian Constitution at Work","q":"Fundamental rights that the government can never ordinarily violate are an example of which function of a constitution?","w":"Rights such as freedom of speech and the right not to be arbitrarily arrested mark out an area the government cannot enter. The chapter treats such rights as the main way a constitution limits government.","o":["Coordination and assurance","Specification of decision-making powers","Limitations on the powers of government","Expression of national identity"],"a":[2]},{"id":"n11icw01-5","p":"n11icw01","n":5,"s":"pol","t":"Indian Constitution at Work","q":"A constitution can also enable the government to fulfil the aspirations of a society. Which feature of the Indian Constitution best shows this?","w":"A constitution can do more than limit power: it can empower the government to remove inequality and deprivation. The Indian Constitution does this through the Directive Principles and special provisions for disadvantaged groups.","o":["It creates a parliamentary system on the British model","It allows the government to take positive steps, such as Directive Principles and protections for weaker sections, to build a just society","It fixes the number of states in India permanently","It makes the President the real head of the government"],"a":[1]},{"id":"n11icw01-6","p":"n11icw01","n":6,"s":"pol","t":"Indian Constitution at Work","q":"Which three factors does the NCERT chapter give for a constitution to be effective and to have real authority?","w":"The chapter says a constitution works when it is made in a way people accept (mode of promulgation), when its provisions are fair to all (substantive provisions) and when power is balanced among institutions (balanced institutional design).","o":["Length, rigidity and a written form","Federalism, judicial review and secularism","Popular elections, a strong executive and a single party","Mode of promulgation, substantive provisions and balanced institutional design"],"a":[3]},{"id":"n11icw01-7","p":"n11icw01","n":7,"s":"pol","t":"Indian Constitution at Work","q":"A constitution drawn up by military rulers or by unpopular leaders, without public participation, is unlikely to be effective. This idea in the chapter relates to:","w":"Mode of promulgation is about who made the constitution and how. A constitution made by a popular, credible body with people's participation, like India's Constituent Assembly after the national movement, carries more legitimacy.","o":["Mode of promulgation","Substantive provisions","Balanced institutional design","Judicial review"],"a":[0]},{"id":"n11icw01-8","p":"n11icw01","n":8,"s":"pol","t":"Indian Constitution at Work","q":"According to the chapter, a well-designed constitution ensures that no single institution or group can destroy it. It does so mainly by:","w":"This is balanced institutional design: power is divided among the legislature, executive, judiciary and independent bodies, so each can check the others, while the constitution stays flexible enough to adapt to changing needs.","o":["Making the constitution impossible to amend","Fragmenting power among institutions so that they check and balance one another","Concentrating power in the executive","Giving all power to the judiciary"],"a":[1]},{"id":"n11icw01-9","p":"n11icw01","n":9,"s":"pol","t":"Indian Constitution at Work","q":"The members of the Constituent Assembly of India were chosen by:","w":"The Constituent Assembly was elected indirectly: members of the provincial assemblies, themselves elected in 1946 under the 1935 Act, chose the members. There was no direct, adult-franchise election.","o":["Direct election by all adult citizens","Nomination by the British Government","Indirect election by the members of the Provincial Legislative Assemblies set up under the Government of India Act, 1935","Nomination by the Indian National Congress"],"a":[2]},{"id":"n11icw01-10","p":"n11icw01","n":10,"s":"pol","t":"Indian Constitution at Work","q":"The composition of the Constituent Assembly broadly followed the plan proposed by:","w":"The Assembly was formed roughly along the lines of the plan of the British Cabinet Mission of 1946, which allotted seats to provinces and princely states according to population.","o":["The Simon Commission","The Cripps Mission","The Cabinet Mission","The Mountbatten Plan"],"a":[2]},{"id":"n11icw01-11","p":"n11icw01","n":11,"s":"pol","t":"Indian Constitution at Work","q":"Under the scheme on which the Constituent Assembly was based, seats were allotted to each province and princely state roughly in proportion to population, in the ratio of about:","w":"Seats were allotted roughly in the ratio of 1:10,00,000, that is, one seat for about every ten lakh people. On this basis the provinces were to elect 292 members and the princely states were allotted at least 93 seats.","o":["One seat for every 1 lakh people","One seat for every 10 lakh people","One seat for every 25 lakh people","One seat for every 1 crore people"],"a":[1]},{"id":"n11icw01-12","p":"n11icw01","n":12,"s":"pol","t":"Indian Constitution at Work","q":"In the provinces, how did the members of each community in the Provincial Legislative Assembly elect their representatives to the Constituent Assembly?","w":"Seats in each province were divided among Muslims, Sikhs and the general category in proportion to population, and each community's members in the assembly elected its representatives by proportional representation with single transferable vote.","o":["By a simple majority (first past the post)","By a list system","By nomination of party leaders","By proportional representation with single transferable vote"],"a":[3]},{"id":"n11icw01-13","p":"n11icw01","n":13,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following statements about the Constituent Assembly:\n1. It held its first sitting on 9 December 1946.\n2. It met again as the Constituent Assembly for divided India on 14 August 1947.\n3. The representatives of the princely states were chosen in a way to be decided by consultation.\nWhich of the statements given above are correct?","w":"All three are correct. After Partition the members from the areas that went to Pakistan left, and the Assembly that reassembled on 14 August 1947 framed the Constitution for India.","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11icw01-14","p":"n11icw01","n":14,"s":"pol","t":"Indian Constitution at Work","q":"The \"Objectives Resolution\", which set out the philosophy behind the Indian Constitution, was moved in the Constituent Assembly in December 1946 by:","w":"Nehru moved the Objectives Resolution on 13 December 1946. It spoke of an independent sovereign republic, a union with autonomous units, and justice, liberty and equality for all; the Preamble grew out of it.","o":["Dr. B.R. Ambedkar","Dr. Rajendra Prasad","Jawaharlal Nehru","Sardar Vallabhbhai Patel"],"a":[2]},{"id":"n11icw01-15","p":"n11icw01","n":15,"s":"pol","t":"Indian Constitution at Work","q":"Who was the chairman of the Drafting Committee of the Constituent Assembly?","w":"Dr. B.R. Ambedkar chaired the Drafting Committee, which prepared the draft constitution that the Assembly debated clause by clause. Dr. Rajendra Prasad was the President of the Constituent Assembly.","o":["Dr. Rajendra Prasad","Dr. B.R. Ambedkar","B.N. Rau","K.M. Munshi"],"a":[1]},{"id":"n11icw01-16","p":"n11icw01","n":16,"s":"pol","t":"Indian Constitution at Work","q":"The Indian Constitution was adopted by the Constituent Assembly and came into effect, respectively, on:","w":"The Constitution was adopted on 26 November 1949 (now observed as Constitution Day) and came into effect on 26 January 1950, the date chosen to recall the 1930 Purna Swaraj pledge.","o":["15 August 1947 and 26 January 1950","26 January 1949 and 26 November 1949","26 November 1949 and 26 January 1950","26 November 1949 and 15 August 1950"],"a":[2]},{"id":"n11icw01-17","p":"n11icw01","n":17,"s":"pol","t":"Indian Constitution at Work","q":"Match the source constitution with the feature India borrowed from it:\nA. British Constitution — 1. Directive Principles of State Policy\nB. Irish Constitution — 2. Charter of fundamental rights and judicial review\nC. United States Constitution — 3. Parliamentary form of government and first past the post\nD. French Constitution — 4. Principles of liberty, equality and fraternity","w":"The chapter's list: Britain gave the parliamentary system, first past the post, rule of law, the Speaker and law-making procedure; Ireland the Directive Principles; the USA fundamental rights, judicial review and an independent judiciary; France liberty, equality and fraternity.","o":["A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2","A-3, B-2, C-1, D-4","A-4, B-1, C-2, D-3"],"a":[0]},{"id":"n11icw01-18","p":"n11icw01","n":18,"s":"pol","t":"Indian Constitution at Work","q":"According to the NCERT chapter, which two ideas did the makers of the Indian Constitution take from the Canadian Constitution?","w":"Canada gave the model of a federation with a strong central government (quasi-federal) and the idea of residual powers, which in India rest with the Union.","o":["A quasi-federal form of government with a strong centre, and the idea of residual powers","Judicial review and impeachment of the President","Directive Principles and the method of electing the President","Emergency provisions and fundamental duties"],"a":[0]},{"id":"n11icw01-19","p":"n11icw01","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is NOT one of the reasons the chapter gives for the authority of the Constituent Assembly and of the Constitution it made?","w":"Members were elected indirectly by the provincial assemblies, not by universal adult franchise. The chapter traces the Assembly's authority to its representativeness, its open deliberation and the legacy of the freedom struggle.","o":["Its members were broadly representative of the different sections and regions of India","It worked by public reason and long deliberation, not by a narrow majority imposing its will","Its members were directly elected by universal adult franchise","It carried forward the consensus built during the national movement"],"a":[2]},{"id":"n11icw01-20","p":"n11icw01","n":20,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following steps in India's constitutional history, mentioned in the chapter:\n1. Motilal Nehru and other Congress leaders drafted a constitution for India.\n2. The Congress, at its Karachi session, resolved on what independent India's constitution should contain, including fundamental rights.\n3. Elections were held to the provincial legislatures under the Government of India Act, 1935.\nWhat is the correct chronological order?","w":"The Nehru Report came in 1928, the Karachi resolution in 1931 and the provincial elections under the 1935 Act in 1937. This long build-up is why the chapter says the Constitution drew on the national movement's experience.","o":["1, 2, 3","2, 1, 3","1, 3, 2","3, 1, 2"],"a":[0]},{"id":"n11icw02-1","p":"n11icw02","n":1,"s":"pol","t":"Indian Constitution at Work","q":"A list of rights mentioned and protected by the constitution is called a:","w":"A Bill of Rights is the list of rights written into and protected by a constitution. It stops the government from acting against them and gives a remedy if they are violated.","o":["Charter of Duties","Instrument of Instructions","Directive Principle","Bill of Rights"],"a":[3]},{"id":"n11icw02-2","p":"n11icw02","n":2,"s":"pol","t":"Indian Constitution at Work","q":"How do Fundamental Rights differ from other rights given by ordinary laws?","w":"Ordinary legal rights are given and changed by ordinary laws. Fundamental Rights are in the Constitution: Parliament can change them only by amending the Constitution, and courts can strike down laws that violate them.","o":["Fundamental Rights are guaranteed and protected by the Constitution itself, and ordinary laws cannot take them away","Fundamental Rights can be changed by any ordinary law of Parliament","Fundamental Rights are only for citizens of states, not union territories","Fundamental Rights cannot be enforced in any court"],"a":[0]},{"id":"n11icw02-3","p":"n11icw02","n":3,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is NOT part of the Right to Equality in the Indian Constitution?","w":"The freedom to form associations and unions is part of the Right to Freedom (Article 19). The Right to Equality covers equality before law, no discrimination, equal opportunity in public employment, abolition of untouchability and abolition of titles.","o":["Equality before law and equal protection of laws","Abolition of untouchability","Abolition of titles","Freedom to form associations and unions"],"a":[3]},{"id":"n11icw02-4","p":"n11icw02","n":4,"s":"pol","t":"Indian Constitution at Work","q":"Reservations in jobs and education for the Scheduled Castes, Scheduled Tribes and backward classes are best explained by which idea in the chapter?","w":"The Constitution itself allows the state to make special provisions and reservations for socially and educationally backward classes, SCs and STs. Such measures are seen as a way to make equality of opportunity real, not a violation of it.","o":["Equality means treating everyone in exactly the same way in all cases","Special measures for disadvantaged groups are needed to achieve real equality of opportunity, and the Constitution allows them","Reservations violate the Right to Equality and are allowed only during an Emergency","Reservations are a Directive Principle and cannot be enforced"],"a":[1]},{"id":"n11icw02-5","p":"n11icw02","n":5,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following freedoms:\n1. Freedom of speech and expression\n2. Freedom to assemble peacefully without arms\n3. Freedom to move freely throughout the territory of India\n4. Freedom to acquire, hold and dispose of property\nWhich of the above are guaranteed to citizens under Article 19 today?","w":"Article 19 now has six freedoms: speech and expression, assembly, association, movement, residence and settlement, and profession, occupation, trade or business. The freedom relating to property was taken out by the 44th Amendment (1978).","o":["1, 2 and 3 only","1, 2, 3 and 4","1 and 3 only","2 and 4 only"],"a":[0]},{"id":"n11icw02-6","p":"n11icw02","n":6,"s":"pol","t":"Indian Constitution at Work","q":"The right to property was removed from the list of Fundamental Rights in 1978. What is its status now?","w":"The 44th Amendment (1978) removed the right to property from Part III. It survives as a constitutional legal right in Article 300A: no one can be deprived of property except by authority of law.","o":["It has been abolished completely","It is a Directive Principle","It is a legal (constitutional) right under Article 300A, not a Fundamental Right","It is a Fundamental Duty"],"a":[2]},{"id":"n11icw02-7","p":"n11icw02","n":7,"s":"pol","t":"Indian Constitution at Work","q":"Which article of the Constitution states that no person shall be deprived of his life or personal liberty except according to procedure established by law?","w":"Article 21 protects life and personal liberty. Courts have read it widely to include, among other things, the right to a livelihood, shelter and a clean environment.","o":["Article 14","Article 19","Article 21","Article 32"],"a":[2]},{"id":"n11icw02-8","p":"n11icw02","n":8,"s":"pol","t":"Indian Constitution at Work","q":"A person arrested under ordinary law must be produced before the nearest magistrate within:","w":"Article 22 gives an arrested person the right to know the grounds of arrest, to consult a lawyer and to be produced before a magistrate within 24 hours, not counting the time taken to travel there.","o":["12 hours of arrest","24 hours of arrest, excluding travel time","48 hours of arrest","7 days of arrest"],"a":[1]},{"id":"n11icw02-9","p":"n11icw02","n":9,"s":"pol","t":"Indian Constitution at Work","q":"Detention of a person on the apprehension that he or she is likely to commit an offence, without a trial, is called:","w":"Under preventive detention a person can be held on suspicion of a likely threat to law and order or security, for a limited period. The chapter notes that it is open to misuse, which is why it is a much-debated provision.","o":["Judicial custody","Habeas corpus","Contempt of court","Preventive detention"],"a":[3]},{"id":"n11icw02-10","p":"n11icw02","n":10,"s":"pol","t":"Indian Constitution at Work","q":"The Right against Exploitation prohibits which of the following?\n1. Traffic in human beings\n2. Forced labour (begar)\n3. Employment of children below 14 years in factories, mines and other hazardous work","w":"Articles 23 and 24 forbid human trafficking, begar and other forced labour, and the employment of children below fourteen in factories, mines or other hazardous work.","o":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11icw02-11","p":"n11icw02","n":11,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following statements about the Right to Freedom of Religion is correct?","w":"Freedom of religion belongs to every person, citizen or not, and is subject to public order, morality and health. India has no state religion, and no religious instruction can be given in institutions wholly maintained out of state funds.","o":["It allows the government to declare an official state religion","It allows religious instruction in every educational institution fully maintained by the state","Every person has the freedom to profess, practise and propagate the religion of his or her choice, subject to public order, morality and health","It applies only to citizens, not to foreigners living in India"],"a":[2]},{"id":"n11icw02-12","p":"n11icw02","n":12,"s":"pol","t":"Indian Constitution at Work","q":"Under the Cultural and Educational Rights, minorities have the right to establish and administer educational institutions of their choice. Minorities here include:","w":"Articles 29 and 30 protect any section of citizens with a distinct language, script or culture, and give religious and linguistic minorities the right to set up and run their own educational institutions.","o":["Only religious minorities","Only linguistic minorities","Religious and linguistic minorities","Only Scheduled Tribes"],"a":[2]},{"id":"n11icw02-13","p":"n11icw02","n":13,"s":"pol","t":"Indian Constitution at Work","q":"Dr. B.R. Ambedkar described which Fundamental Right as \"the heart and soul\" of the Constitution?","w":"The Right to Constitutional Remedies (Article 32) lets a citizen go straight to the Supreme Court to enforce Fundamental Rights. Without it the other rights would be only promises, which is why Ambedkar gave it this name.","o":["Right to Equality","Right to Freedom","Right to Constitutional Remedies","Right to Freedom of Religion"],"a":[2]},{"id":"n11icw02-14","p":"n11icw02","n":14,"s":"pol","t":"Indian Constitution at Work","q":"Match the writ with what it does:\nA. Habeas corpus — 1. Orders a public official to perform a legal duty that is not being done\nB. Mandamus — 2. Orders that an arrested person be produced before the court\nC. Quo warranto — 3. Transfers a case from a lower court to a higher court or authority\nD. Certiorari — 4. Asks a person by what authority he holds a public office","w":"Habeas corpus brings an arrested person before the court; mandamus compels a public duty; quo warranto questions a person's right to hold an office; certiorari moves a case up to a higher court or authority. The fifth writ, prohibition, stops a lower court from going beyond its jurisdiction.","o":["A-2, B-1, C-4, D-3","A-1, B-2, C-3, D-4","A-2, B-4, C-1, D-3","A-3, B-1, C-4, D-2"],"a":[0]},{"id":"n11icw02-15","p":"n11icw02","n":15,"s":"pol","t":"Indian Constitution at Work","q":"Which writ is issued by a higher court to a lower court when the lower court goes beyond its jurisdiction, ordering it to stop the proceedings?","w":"Prohibition prevents a lower court from continuing with a case that falls outside its jurisdiction. Certiorari, by contrast, transfers a matter to the higher court or authority.","o":["Mandamus","Prohibition","Quo warranto","Habeas corpus"],"a":[1]},{"id":"n11icw02-16","p":"n11icw02","n":16,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following statements about the National Human Rights Commission (NHRC), as described in the chapter:\n1. It was set up by a law passed in 1993.\n2. It can enquire into complaints of human rights violations on its own or on a petition.\n3. Its decisions are final and binding on the government, like a court order.\nWhich of the statements given above are correct?","w":"The NHRC was created under the Protection of Human Rights Act, 1993, and can investigate complaints and visit jails. It cannot itself punish: it recommends action to the government, so statement 3 is wrong.","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"a":[0]},{"id":"n11icw02-17","p":"n11icw02","n":17,"s":"pol","t":"Indian Constitution at Work","q":"Directive Principles of State Policy are described as \"non-justiciable\". This means that:","w":"No court can order the government to implement a Directive Principle. Still, they are fundamental in the governance of the country, and the government is expected to apply them while making laws and policies.","o":["Citizens cannot go to court to have them enforced","They are not part of the Constitution","Courts can strike down any law that follows them","They apply only to state governments"],"a":[0]},{"id":"n11icw02-18","p":"n11icw02","n":18,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is a Directive Principle and NOT a Fundamental Right?","w":"Equal pay for equal work for men and women is a Directive Principle (Article 39). The other three are Fundamental Rights that can be enforced in court.","o":["Protection against untouchability","Freedom of conscience","Protection against forced labour","Equal pay for equal work for men and women"],"a":[3]},{"id":"n11icw02-19","p":"n11icw02","n":19,"s":"pol","t":"Indian Constitution at Work","q":"The list of Fundamental Duties of citizens was added to the Constitution by:","w":"The 42nd Amendment (1976) inserted Part IVA with the Fundamental Duties, such as respecting the Constitution, the national flag and the national anthem. They are not enforceable in court, and they do not make the Fundamental Rights conditional on them.","o":["The 24th Amendment, 1971","The 42nd Amendment, 1976","The 44th Amendment, 1978","The 73rd Amendment, 1992"],"a":[1]},{"id":"n11icw02-20","p":"n11icw02","n":20,"s":"pol","t":"Indian Constitution at Work","q":"How does the chapter explain the relationship between Fundamental Rights and Directive Principles?","w":"Fundamental Rights protect individuals by limiting the state; Directive Principles push the state to work for social and economic justice. When policies such as land reforms clashed with the right to property, the conflict was resolved through amendments and court judgments.","o":["Directive Principles always override Fundamental Rights","They have nothing to do with each other","They often complement each other: rights restrain the government, while Directive Principles urge it to act; at times the two have conflicted, for example over the right to property","Fundamental Rights are only for the government and Directive Principles only for citizens"],"a":[2]},{"id":"n11icw03-1","p":"n11icw03","n":1,"s":"pol","t":"Indian Constitution at Work","q":"Why does the chapter say that elections are needed in most democracies?","w":"Direct democracy, where citizens decide everything themselves, is possible only in small communities. In a country like India people rule through representatives, and elections are how they choose and change them.","o":["Because all citizens can take every decision directly in large modern societies","Because the courts cannot work without elected judges","Because in large societies citizens cannot take every decision directly, so they choose representatives who govern on their behalf","Because the Constitution forbids direct democracy"],"a":[2]},{"id":"n11icw03-2","p":"n11icw03","n":2,"s":"pol","t":"Indian Constitution at Work","q":"In the \"first past the post\" (FPTP) system, the candidate who wins is the one who:","w":"Under FPTP, also called the plurality system, the candidate with the most votes wins the seat; a majority of votes is not needed. India uses it for the Lok Sabha and the state legislative assemblies.","o":["Gets more than half of all the votes polled","Gets the largest number of second-preference votes","Is placed first on the party's list","Gets more votes than any other candidate, even if less than half of the total"],"a":[3]},{"id":"n11icw03-3","p":"n11icw03","n":3,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is a feature of the proportional representation (PR) system?","w":"In PR, a party's share of seats roughly matches its share of votes. Option 3 describes a common result of FPTP, where a party can win a large majority of seats with well under half the votes.","o":["The country is always divided into small single-member constituencies","A party gets seats roughly in proportion to its share of votes","The winner need not get a majority of votes in any constituency, and the party with the most seats may get far more seats than its vote share","Voters vote for individual candidates only and never for parties"],"a":[1]},{"id":"n11icw03-4","p":"n11icw03","n":4,"s":"pol","t":"Indian Constitution at Work","q":"The chapter uses the example of a country where the whole country is treated as one constituency and seats are given to parties in proportion to their votes. Which country is it?","w":"In Israel, voters vote for parties and the whole country is one constituency; each party gets seats in the Knesset in proportion to its national vote share, provided it crosses a minimum threshold.","o":["Israel","United Kingdom","United States","Canada"],"a":[0]},{"id":"n11icw03-5","p":"n11icw03","n":5,"s":"pol","t":"Indian Constitution at Work","q":"In India, the proportional representation system with single transferable vote is used to elect:\n1. Members of the Rajya Sabha\n2. The President\n3. The Vice-President\n4. Members of the Lok Sabha","w":"The Rajya Sabha, the President, the Vice-President and the state legislative councils are elected by PR with single transferable vote. The Lok Sabha and state assemblies use first past the post.","o":["1, 2 and 3 only","1 and 4 only","2 and 3 only","1, 2, 3 and 4"],"a":[0]},{"id":"n11icw03-6","p":"n11icw03","n":6,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is NOT a reason the chapter gives for India's choice of the first past the post system?","w":"FPTP does not give seats in proportion to votes; that is the aim of PR. The makers of the Constitution chose FPTP for its simplicity, its link between voters and a local representative, and its tendency to give stable majorities.","o":["It is simple to understand, even for voters with little knowledge of politics","It gives voters a clear choice between candidates and a representative for their area","It always gives every party seats exactly in proportion to its votes","It tends to produce stable governments"],"a":[2]},{"id":"n11icw03-7","p":"n11icw03","n":7,"s":"pol","t":"Indian Constitution at Work","q":"In the Rajya Sabha elections, which voters elect the representatives of a state?","w":"Members of the Rajya Sabha are elected by the elected members of the state Legislative Assembly, using PR with single transferable vote. Voters rank candidates in order of preference.","o":["All adult citizens of the state","The members of the Lok Sabha from that state","The members of the state's panchayats and municipalities","The members of the state's Legislative Assembly"],"a":[3]},{"id":"n11icw03-8","p":"n11icw03","n":8,"s":"pol","t":"Indian Constitution at Work","q":"The Constituent Assembly rejected separate electorates for disadvantaged groups and chose instead:","w":"Separate electorates, used under British rule, let only members of a community vote for its candidates. The Constitution chose reserved constituencies: only SC or ST candidates can stand, but every voter in the constituency votes.","o":["Nominated members for each community","Reserved constituencies, where only candidates from the group can contest but all voters of the constituency vote","A separate list of voters for each caste","Proportional representation for the Lok Sabha"],"a":[1]},{"id":"n11icw03-9","p":"n11icw03","n":9,"s":"pol","t":"Indian Constitution at Work","q":"Which body decides which constituencies will be reserved for the Scheduled Castes and Scheduled Tribes?","w":"The Delimitation Commission, set up by the President and working with the Election Commission, draws constituency boundaries and decides which ones are reserved, based on the population of SCs and STs.","o":["The Election Commission of India","The Supreme Court","The Delimitation Commission","The National Commission for Scheduled Castes"],"a":[2]},{"id":"n11icw03-10","p":"n11icw03","n":10,"s":"pol","t":"Indian Constitution at Work","q":"On what basis are constituencies reserved for the Scheduled Tribes chosen?","w":"For the STs, the constituencies with the largest proportion of ST population are reserved. For the SCs, the Delimitation Commission looks at constituencies with a high share of SC population and also spreads them across the state.","o":["Constituencies where STs are more than half of all voters, only","Constituencies with the highest share of ST population","By lottery among all constituencies","Constituencies chosen by the ruling party"],"a":[1]},{"id":"n11icw03-11","p":"n11icw03","n":11,"s":"pol","t":"Indian Constitution at Work","q":"The 61st Amendment, which applied from the 1989 elections, changed the minimum voting age in India from:","w":"The 61st Amendment (1988) lowered the voting age from 21 to 18, bringing millions of young people onto the voters' list from the 1989 elections.","o":["25 years to 21 years","21 years to 18 years","18 years to 16 years","21 years to 19 years"],"a":[1]},{"id":"n11icw03-12","p":"n11icw03","n":12,"s":"pol","t":"Indian Constitution at Work","q":"\"Universal adult franchise\" means that:","w":"Every citizen above the voting age can vote. India adopted it from the first election, unlike many older democracies where women and the poor got the vote only gradually.","o":["Every adult citizen has the right to vote, without restrictions of property, education, caste, religion or gender","Only educated adults can vote","Only taxpayers can vote","Every adult has to vote by law"],"a":[0]},{"id":"n11icw03-13","p":"n11icw03","n":13,"s":"pol","t":"Indian Constitution at Work","q":"The minimum age to contest an election to the Lok Sabha is:","w":"A candidate must be at least 25 years old to contest the Lok Sabha or a state Legislative Assembly, and 30 years for the Rajya Sabha or a Legislative Council.","o":["18 years","21 years","25 years","30 years"],"a":[2]},{"id":"n11icw03-14","p":"n11icw03","n":14,"s":"pol","t":"Indian Constitution at Work","q":"Which article of the Constitution provides for an Election Commission for the superintendence, direction and control of elections?","w":"Article 324 sets up the Election Commission and gives it the superintendence, direction and control of elections to Parliament, the state legislatures and the offices of President and Vice-President.","o":["Article 280","Article 356","Article 368","Article 324"],"a":[3]},{"id":"n11icw03-15","p":"n11icw03","n":15,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following statements about the Election Commission of India:\n1. It has had more than one member since 1993, with the Chief Election Commissioner presiding.\n2. The Chief Election Commissioner can be removed only in the way a Supreme Court judge is removed.\n3. Elections to panchayats and municipalities are conducted by the Election Commission of India.\nWhich of the statements given above are correct?","w":"Since 1993 the Commission has had three members. The CEC enjoys the security of tenure of a Supreme Court judge. Panchayat and municipal elections are conducted by the State Election Commissions, not the ECI.","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"a":[0]},{"id":"n11icw03-16","p":"n11icw03","n":16,"s":"pol","t":"Indian Constitution at Work","q":"In each state, the work of the Election Commission is assisted by:","w":"A Chief Electoral Officer in each state, with officers in each district and constituency, runs the election machinery under the Election Commission's direction.","o":["The Governor","The Advocate General","The Chief Electoral Officer","The State Public Service Commission"],"a":[2]},{"id":"n11icw03-17","p":"n11icw03","n":17,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is a function of the Election Commission of India?\n1. Preparing and updating the voters' list\n2. Deciding the election schedule\n3. Recognising political parties and allotting symbols\n4. Deciding the number of seats in the Lok Sabha","w":"The ECI prepares electoral rolls, fixes the schedule, enforces the Model Code of Conduct and recognises parties and allots symbols. The number of seats is fixed by the Constitution and laws of Parliament, not by the Commission.","o":["1, 2 and 3 only","1 and 2 only","3 and 4 only","1, 2, 3 and 4"],"a":[0]},{"id":"n11icw03-18","p":"n11icw03","n":18,"s":"pol","t":"Indian Constitution at Work","q":"Under the first past the post system, which of the following outcomes is possible?","w":"Because each seat goes to whoever is ahead, a party that leads narrowly in many constituencies can win a big majority of seats with well under half the votes. The chapter shows this with an example from a Lok Sabha election.","o":["A party wins a large majority of seats with much less than half of the votes","Every party gets seats exactly equal to its vote share","A candidate needs more than 50% of votes to win","Small parties always get more seats than their vote share"],"a":[0]},{"id":"n11icw03-19","p":"n11icw03","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following has been suggested as an electoral reform in the chapter?","w":"Suggestions discussed include more representation for women, stricter rules on election spending, barring candidates with serious criminal cases and more powers for the Election Commission. Reform depends on vigilant citizens as much as on laws.","o":["Abolishing the Election Commission","Ending universal adult franchise","Steps to reduce the role of money and criminals in elections and to give more representation to women","Allowing only national parties to contest"],"a":[2]},{"id":"n11icw03-20","p":"n11icw03","n":20,"s":"pol","t":"Indian Constitution at Work","q":"Who conducts the election of the President of India?","w":"Article 324 places elections to the offices of President and Vice-President, as well as to Parliament and state legislatures, under the Election Commission of India.","o":["The Speaker of the Lok Sabha","The Chief Justice of India","The Union Home Ministry","The Election Commission of India"],"a":[3]},{"id":"n11icw04-1","p":"n11icw04","n":1,"s":"pol","t":"Indian Constitution at Work","q":"The executive is the organ of government that primarily:","w":"The legislature makes laws, the judiciary interprets them, and the executive carries them out. The executive includes the political leaders who head the government and the civil servants who run the administration.","o":["Makes laws","Interprets laws and settles disputes","Implements laws and policies and runs the administration","Conducts elections"],"a":[2]},{"id":"n11icw04-2","p":"n11icw04","n":2,"s":"pol","t":"Indian Constitution at Work","q":"The political executive and the permanent executive differ in that:","w":"Ministers are the political executive: they come through elections and change with governments. Civil servants are the permanent executive, appointed on merit and continuing in office whichever party is in power.","o":["The political executive is elected for a fixed period, while civil servants are appointed for long-term careers","The political executive is appointed by the UPSC","The permanent executive changes after every election","Civil servants are responsible to the voters directly"],"a":[0]},{"id":"n11icw04-3","p":"n11icw04","n":3,"s":"pol","t":"Indian Constitution at Work","q":"In which system is the head of the government also the head of the state, elected for a fixed term and not removable by a vote of the legislature (except by impeachment)?","w":"In a presidential system, as in the USA or Brazil, the President is both head of state and head of government and is elected for a fixed term. The legislature can remove him only by impeachment.","o":["Parliamentary system","Semi-presidential system","Constitutional monarchy","Presidential system"],"a":[3]},{"id":"n11icw04-4","p":"n11icw04","n":4,"s":"pol","t":"Indian Constitution at Work","q":"A system with both a President and a Prime Minister, where the President has important day-to-day powers and may belong to a different party from the Prime Minister, is called:","w":"In a semi-presidential system, as in France or Sri Lanka, the President is directly elected and has real powers, while the Prime Minister and cabinet must also have the legislature's support.","o":["Presidential","Parliamentary","Semi-presidential","Federal"],"a":[2]},{"id":"n11icw04-5","p":"n11icw04","n":5,"s":"pol","t":"Indian Constitution at Work","q":"Why did the makers of the Indian Constitution choose the parliamentary executive?","w":"The framers wanted an executive that is responsible to the legislature and, through it, to the people. They were also familiar with the parliamentary system from the colonial period.","o":["Because it makes the executive answerable to and controlled by the people's representatives","Because it gives the President unlimited powers","Because the President is directly elected by the people","Because it removes the need for a legislature"],"a":[0]},{"id":"n11icw04-6","p":"n11icw04","n":6,"s":"pol","t":"Indian Constitution at Work","q":"The President of India is elected by:","w":"The President is elected indirectly by an electoral college of elected MPs and elected MLAs, using proportional representation with single transferable vote. Nominated members do not vote.","o":["All adult citizens of India","The members of the Lok Sabha only","The elected members of both Houses of Parliament and of the Legislative Assemblies of the states (and of Delhi and Puducherry)","The members of the Rajya Sabha and the Council of Ministers"],"a":[2]},{"id":"n11icw04-7","p":"n11icw04","n":7,"s":"pol","t":"Indian Constitution at Work","q":"On which ground can the President of India be removed from office by impeachment?","w":"The only ground for impeachment is violation of the Constitution. Impeachment needs a special majority in both Houses of Parliament.","o":["Violation of the Constitution","Loss of majority in the Lok Sabha","Disagreement with the Prime Minister","Refusal to sign a money bill"],"a":[0]},{"id":"n11icw04-8","p":"n11icw04","n":8,"s":"pol","t":"Indian Constitution at Work","q":"Article 74(1) of the Constitution provides that the President acts on:","w":"Under Article 74(1) there is a Council of Ministers with the Prime Minister at the head to aid and advise the President, who acts in accordance with that advice. Real executive power therefore lies with the council.","o":["His or her own judgement in all matters","The aid and advice of the Council of Ministers headed by the Prime Minister","The advice of the Chief Justice of India","The advice of the Governors of the states"],"a":[1]},{"id":"n11icw04-9","p":"n11icw04","n":9,"s":"pol","t":"Indian Constitution at Work","q":"After the 42nd and 44th Amendments, what can the President do if he or she disagrees with the advice of the Council of Ministers?","w":"The 42nd Amendment (1976) made the advice binding. The 44th Amendment (1978) let the President send it back once for reconsideration, but the President is bound by the advice given after reconsideration.","o":["Reject the advice permanently","Ask the council to reconsider it once; if the council sends the same advice again, the President must act on it","Dismiss the Council of Ministers at will","Refer the matter to the Supreme Court in every case"],"a":[1]},{"id":"n11icw04-10","p":"n11icw04","n":10,"s":"pol","t":"Indian Constitution at Work","q":"When the President neither signs a bill nor returns it to Parliament, keeping it pending without any time limit, this is popularly called:","w":"The Constitution sets no time limit for the President to decide on a bill (other than a money bill or a constitutional amendment). Keeping a bill pending indefinitely is called the pocket veto. President Zail Singh used it in 1986 on the Indian Post Office (Amendment) Bill.","o":["Absolute veto","Pocket veto","Suspensive veto","Qualified veto"],"a":[1]},{"id":"n11icw04-11","p":"n11icw04","n":11,"s":"pol","t":"Indian Constitution at Work","q":"In which situation does the President of India have real discretion in appointing a Prime Minister?","w":"If one party or alliance has a clear majority, the President must invite its leader. Discretion comes in when the result is unclear: the President then judges who is most likely to win the confidence of the Lok Sabha.","o":["When the ruling party has a clear majority in the Lok Sabha","When a money bill is to be introduced","When the Rajya Sabha is dissolved","When no party or coalition has a clear majority after an election"],"a":[3]},{"id":"n11icw04-12","p":"n11icw04","n":12,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following statements about the Vice-President of India:\n1. He or she is elected by the members of both Houses of Parliament.\n2. He or she is the ex officio Chairman of the Rajya Sabha.\n3. He or she acts as President when the office of President falls vacant, until a new President is elected.\nWhich of the statements given above are correct?","w":"All three are correct. The Vice-President holds office for five years and can be removed by a resolution of the Rajya Sabha passed by a majority and agreed to by the Lok Sabha.","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11icw04-13","p":"n11icw04","n":13,"s":"pol","t":"Indian Constitution at Work","q":"The Prime Minister is appointed by the President, but to remain in office the Prime Minister must:","w":"The Prime Minister and the Council of Ministers stay in office only as long as they have the confidence of the Lok Sabha. If they lose a vote of confidence or a no-confidence motion succeeds, they must resign.","o":["Have the support (confidence) of a majority in the Lok Sabha","Be a member of the Rajya Sabha","Have the support of a majority of state governments","Win a direct national election"],"a":[0]},{"id":"n11icw04-14","p":"n11icw04","n":14,"s":"pol","t":"Indian Constitution at Work","q":"A person who is not a Member of Parliament can be appointed a minister, but must become a member of either House within:","w":"A minister who is not an MP has to get elected or nominated to either House within six months, or cease to be a minister.","o":["Three months","One year","Two years","Six months"],"a":[3]},{"id":"n11icw04-15","p":"n11icw04","n":15,"s":"pol","t":"Indian Constitution at Work","q":"The 91st Amendment (2003) limited the total number of ministers, including the Prime Minister, to:","w":"The 91st Amendment capped the size of the Council of Ministers at 15 percent of the total strength of the Lok Sabha (and, in states, of the Legislative Assembly).","o":["10 percent of the members of the Lok Sabha","15 percent of the members of the Lok Sabha","20 percent of the total members of both Houses","25 percent of the members of the Rajya Sabha"],"a":[1]},{"id":"n11icw04-16","p":"n11icw04","n":16,"s":"pol","t":"Indian Constitution at Work","q":"The principle of \"collective responsibility\" of the Council of Ministers means that:","w":"The council works as a team. A vote against one ministry's policy is a vote against the whole government, and ministers who disagree with a cabinet decision are expected to accept it or resign.","o":["Each minister answers only to the Prime Minister","Ministers are responsible only to the President","If the Lok Sabha passes a no-confidence motion, the whole Council of Ministers has to resign, and ministers stand by cabinet decisions in public","Ministers are responsible to the courts for every decision"],"a":[2]},{"id":"n11icw04-17","p":"n11icw04","n":17,"s":"pol","t":"Indian Constitution at Work","q":"The chapter describes the Prime Minister's position as central for several reasons. Which of the following is NOT one of them?","w":"The Prime Minister is not directly elected by the whole country; he or she is a member of Parliament who leads the majority. Coalition governments since 1989 have made the Prime Minister's position depend more on allies.","o":["The Prime Minister chooses the ministers and allocates portfolios","The Prime Minister heads the Council of Ministers and links it with the President and Parliament","The Prime Minister is directly elected by all the voters of India","The Prime Minister usually leads the majority party or coalition in the Lok Sabha"],"a":[2]},{"id":"n11icw04-18","p":"n11icw04","n":18,"s":"pol","t":"Indian Constitution at Work","q":"Members of the All India Services, such as the IAS and IPS, are:","w":"IAS and IPS officers are recruited through the UPSC and allotted to state cadres. They work under the state government, but only the Centre can take disciplinary action against them.","o":["Recruited by the Union Public Service Commission and serve in the states under the state governments, but can be disciplined only by the Central Government","Recruited by the states and work only for the Centre","Elected by the people of each district","Appointed by the Governor and can be removed by the state government at any time"],"a":[0]},{"id":"n11icw04-19","p":"n11icw04","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Why does the Constitution give civil servants security of service?","w":"Civil servants must carry out the policies of whichever government is elected, but neutrally. Security of service protects them from political pressure, while ministers remain responsible for policy.","o":["So that they can join political parties","So that they never have to follow the instructions of ministers","So that they can make laws","So that they can do their work impartially and efficiently, without fear of the party in power"],"a":[3]},{"id":"n11icw04-20","p":"n11icw04","n":20,"s":"pol","t":"Indian Constitution at Work","q":"Which body recruits civil servants for the central services through competitive examinations?","w":"The Union Public Service Commission conducts the examinations for the all-India and central services; each state has a State Public Service Commission for its own services. Their members have security of tenure.","o":["Election Commission of India","Staff Selection Commission of the states","Union Public Service Commission","Finance Commission"],"a":[2]},{"id":"n11icw05-1","p":"n11icw05","n":1,"s":"pol","t":"Indian Constitution at Work","q":"A legislature with two Houses is called:","w":"A bicameral legislature has two Houses, like India's Parliament (Lok Sabha and Rajya Sabha). Some states also have two Houses: a Legislative Assembly and a Legislative Council.","o":["Unicameral","Federal","Plural","Bicameral"],"a":[3]},{"id":"n11icw05-2","p":"n11icw05","n":2,"s":"pol","t":"Indian Constitution at Work","q":"Why does the chapter say a second House is useful in a large and diverse federal country like India?","w":"The Rajya Sabha represents the states and lets every decision be considered twice. A hasty decision of one House can be checked by the other.","o":["It allows the representation of the states and gives an opportunity to reconsider decisions taken by the other House","It makes the passing of laws impossible","It replaces the need for elections","It gives the President a vote in Parliament"],"a":[0]},{"id":"n11icw05-3","p":"n11icw05","n":3,"s":"pol","t":"Indian Constitution at Work","q":"In the United States Senate every state has equal representation. The Indian Rajya Sabha follows a different principle, in which:","w":"India follows asymmetrical representation: Uttar Pradesh has 31 Rajya Sabha members while small states such as Sikkim have one. In the US, each state elects two senators whatever its size.","o":["Every state has exactly two members","States are represented roughly according to their population, so bigger states get more members","Only union territories are represented","Members are nominated by the President for all states"],"a":[1]},{"id":"n11icw05-4","p":"n11icw05","n":4,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following statements about the Rajya Sabha:\n1. It is a permanent House and is never dissolved.\n2. Its members are elected for six years, and one-third of them retire every two years.\n3. The President nominates twelve members with distinction in literature, science, art and social service.\nWhich of the statements given above are correct?","w":"All three are correct. Because one-third of the members retire every second year, the Rajya Sabha never goes out of existence; its composition changes gradually.","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11icw05-5","p":"n11icw05","n":5,"s":"pol","t":"Indian Constitution at Work","q":"Members of the Lok Sabha are elected:","w":"Lok Sabha members are directly elected by the voters of single-member constituencies using first past the post. The House has a five-year term but can be dissolved earlier.","o":["Directly by the people from territorial constituencies, normally for five years","By the state legislative assemblies","By the Rajya Sabha","By the President, on the advice of the Prime Minister"],"a":[0]},{"id":"n11icw05-6","p":"n11icw05","n":6,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following powers belongs exclusively to the Lok Sabha?","w":"The Council of Ministers is responsible only to the Lok Sabha, so only the Lok Sabha can remove it through a no-confidence motion. The other powers are shared with the Rajya Sabha.","o":["Electing the Vice-President","Taking part in the impeachment of the President","Approving constitutional amendments","Passing a no-confidence motion that can remove the Council of Ministers"],"a":[3]},{"id":"n11icw05-7","p":"n11icw05","n":7,"s":"pol","t":"Indian Constitution at Work","q":"A money bill can be introduced:","w":"Money bills can be introduced only in the Lok Sabha. The Rajya Sabha can only suggest changes, which the Lok Sabha may accept or reject.","o":["In either House of Parliament","Only in the Rajya Sabha","Only in the Lok Sabha","Only in a joint sitting of both Houses"],"a":[2]},{"id":"n11icw05-8","p":"n11icw05","n":8,"s":"pol","t":"Indian Constitution at Work","q":"For how many days at most can the Rajya Sabha delay a money bill?","w":"If the Rajya Sabha does not return a money bill within 14 days, it is deemed to have been passed by both Houses in the form in which the Lok Sabha passed it.","o":["14 days","7 days","30 days","6 months"],"a":[0]},{"id":"n11icw05-9","p":"n11icw05","n":9,"s":"pol","t":"Indian Constitution at Work","q":"Who decides whether a bill is a money bill?","w":"The Speaker certifies whether a bill is a money bill, and that decision is final for the purposes of passing it.","o":["The President","The Chairman of the Rajya Sabha","The Speaker of the Lok Sabha","The Finance Minister"],"a":[2]},{"id":"n11icw05-10","p":"n11icw05","n":10,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is a special power of the Rajya Sabha that the Lok Sabha does not have?","w":"Under Article 249 the Rajya Sabha, by a two-thirds majority of members present and voting, can let Parliament legislate on a State List subject. It also has a special role in creating new All India Services.","o":["Passing a no-confidence motion","Introducing a money bill","Authorising Parliament to make a law on a subject in the State List in the national interest","Approving the Union Budget"],"a":[2]},{"id":"n11icw05-11","p":"n11icw05","n":11,"s":"pol","t":"Indian Constitution at Work","q":"If the two Houses of Parliament disagree on an ordinary bill, the deadlock is resolved by:","w":"The President can summon a joint sitting of both Houses, presided over by the Speaker. Since the Lok Sabha has more members, its view usually prevails.","o":["A decision of the President alone","A joint sitting of both Houses","A reference to the Supreme Court","A national referendum"],"a":[1]},{"id":"n11icw05-12","p":"n11icw05","n":12,"s":"pol","t":"Indian Constitution at Work","q":"Put the stages of an ordinary bill in the correct order:\n1. The bill is sent to the other House\n2. The bill is introduced and discussed in one House, often after a committee examines it\n3. The bill receives the President's assent and becomes an Act\n4. The bill is passed in the House where it was introduced","w":"A bill is introduced and discussed, examined by a committee if needed, passed by the first House, then goes through the same steps in the second House, and becomes law after the President's assent.","o":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","1, 2, 4, 3"],"a":[0]},{"id":"n11icw05-13","p":"n11icw05","n":13,"s":"pol","t":"Indian Constitution at Work","q":"The hour at the start of a sitting when members ask ministers questions on government work is called:","w":"Question Hour is one of the main ways Parliament keeps the executive accountable. Zero Hour, which follows it, lets members raise urgent matters, though it is not mentioned in the rules.","o":["Zero Hour","Adjournment motion","Calling attention","Question Hour"],"a":[3]},{"id":"n11icw05-14","p":"n11icw05","n":14,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following are ways in which Parliament controls the executive?\n1. Debates and discussions\n2. Approval or refusal of laws and of the budget\n3. Financial control through grants\n4. No-confidence motion","w":"The chapter lists all of these. Parliament can debate policies, refuse laws and money the executive needs, examine spending, and finally remove the government through a no-confidence motion in the Lok Sabha.","o":["1 and 2 only","2, 3 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"a":[3]},{"id":"n11icw05-15","p":"n11icw05","n":15,"s":"pol","t":"Indian Constitution at Work","q":"Why does Parliament work through committees?","w":"Standing committees, including those for each group of ministries, and joint committees study bills, budget grants and policies in detail. Their reports help the House decide.","o":["Because the Constitution bans debates in the House","Because the House cannot examine every bill and the spending of every ministry in detail in its limited time","Because committees replace the need for the President's assent","Because committee members are directly elected by the people"],"a":[1]},{"id":"n11icw05-16","p":"n11icw05","n":16,"s":"pol","t":"Indian Constitution at Work","q":"The anti-defection law was added to the Constitution by:","w":"The 52nd Amendment (1985), with later changes in 2003, created the Tenth Schedule. A member who defects can be disqualified from the House.","o":["The 42nd Amendment, 1976","The 44th Amendment, 1978","The 52nd Amendment, 1985","The 61st Amendment, 1988"],"a":[2]},{"id":"n11icw05-17","p":"n11icw05","n":17,"s":"pol","t":"Indian Constitution at Work","q":"Under the anti-defection law, who decides whether a member of the Lok Sabha should be disqualified for defection?","w":"The presiding officer of the House (the Speaker or the Chairman) decides on disqualification for defection. Courts can review these decisions.","o":["The President","The Election Commission","The Speaker of the Lok Sabha","The Prime Minister"],"a":[2]},{"id":"n11icw05-18","p":"n11icw05","n":18,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following counts as defection under the anti-defection law?","w":"Defection means voluntarily leaving one's party, or voting or abstaining against its whip in the House without permission. The law was made to stop legislators from changing sides for gain.","o":["A member voting against the party's direction in the House, or voluntarily giving up party membership","A member asking a question in Question Hour","A member speaking in a committee","A member contesting from a different constituency in the next election"],"a":[0]},{"id":"n11icw05-19","p":"n11icw05","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Who presides over a joint sitting of the two Houses of Parliament?","w":"The Speaker presides over a joint sitting. The Speaker is also the key officer who keeps order in the Lok Sabha and protects the rights of members.","o":["The President","The Speaker of the Lok Sabha","The Vice-President","The Prime Minister"],"a":[1]},{"id":"n11icw05-20","p":"n11icw05","n":20,"s":"pol","t":"Indian Constitution at Work","q":"Besides making laws, Parliament has other functions. Which of the following is an electoral or judicial function of Parliament?","w":"MPs take part in electing the President and elect the Vice-President, and Parliament alone can impeach the President and remove judges of the Supreme Court and High Courts. Appointments of judges and the conduct of elections are done by other bodies.","o":["Appointing the Chief Justice of India","Recruiting civil servants","Conducting elections to state assemblies","Electing the President and the Vice-President, and removing the President and judges of higher courts through special procedures"],"a":[3]},{"id":"n11icw06-1","p":"n11icw06","n":1,"s":"pol","t":"Indian Constitution at Work","q":"\"Independence of the judiciary\" means that:","w":"Independence does not mean arbitrariness or lack of accountability. It means the legislature and executive cannot obstruct the judiciary, so judges can do justice impartially.","o":["Judges can act in any way they like, without being accountable to anyone","The judiciary can make laws on any subject","Other organs of government must not interfere in the judiciary's work, so that judges can decide without fear or favour","Judges are elected by the people"],"a":[2]},{"id":"n11icw06-2","p":"n11icw06","n":2,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following provisions helps keep the Indian judiciary independent?\n1. Judges have security of tenure and can be removed only by a difficult procedure\n2. The salaries and allowances of judges are not subject to a vote of the legislature\n3. The conduct of judges cannot be discussed in the legislature except during a removal motion","w":"All three protect independence. Judges' salaries are charged on the Consolidated Fund, their removal is very difficult, and the judiciary can punish contempt of court.","o":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11icw06-3","p":"n11icw06","n":3,"s":"pol","t":"Indian Constitution at Work","q":"In the appointment of judges of the Supreme Court, the practice that has emerged from court judgments is that recommendations are made by:","w":"Since the 1990s, the Supreme Court's judgments have given the senior judges the main say. A group of the Chief Justice and four senior-most judges, the collegium, recommends names; the President makes the appointment.","o":["The Prime Minister alone","The Law Minister and the Attorney General","A collegium of the Chief Justice of India and the four senior-most judges of the Supreme Court","The Union Public Service Commission"],"a":[2]},{"id":"n11icw06-4","p":"n11icw06","n":4,"s":"pol","t":"Indian Constitution at Work","q":"By convention, the Chief Justice of India is usually:","w":"The convention is to appoint the senior-most judge as Chief Justice. It was broken twice in the 1970s, when senior judges were superseded, and both decisions were controversial.","o":["The senior-most judge of the Supreme Court","The youngest judge of the Supreme Court","A judge chosen by the Lok Sabha","The Attorney General of India"],"a":[0]},{"id":"n11icw06-5","p":"n11icw06","n":5,"s":"pol","t":"Indian Constitution at Work","q":"On what grounds can a judge of the Supreme Court or a High Court be removed?","w":"A judge can be removed only for proven misbehaviour or incapacity, through a motion passed by a special majority in both Houses of Parliament. No judge has been removed so far.","o":["Political disagreement with the government","A no-confidence motion in the Lok Sabha","A decision of the President alone","Proven misbehaviour or incapacity"],"a":[3]},{"id":"n11icw06-6","p":"n11icw06","n":6,"s":"pol","t":"Indian Constitution at Work","q":"The chapter mentions a 1991 removal motion against a Supreme Court judge that failed in Parliament. Who was the judge?","w":"The motion against Justice V. Ramaswami got two-thirds of the members present but not the support of a majority of the total strength of the House, because the ruling party did not vote. It shows how hard removal is.","o":["Justice P.N. Bhagwati","Justice V.R. Krishna Iyer","Justice V. Ramaswami","Justice H.R. Khanna"],"a":[2]},{"id":"n11icw06-7","p":"n11icw06","n":7,"s":"pol","t":"Indian Constitution at Work","q":"Disputes between the Union and one or more states, or between states, come directly to the Supreme Court under its:","w":"In its original jurisdiction the Supreme Court hears certain cases first, without them going to a lower court. Federal disputes between the Centre and the states are the main example.","o":["Original jurisdiction","Appellate jurisdiction","Advisory jurisdiction","Writ jurisdiction"],"a":[0]},{"id":"n11icw06-8","p":"n11icw06","n":8,"s":"pol","t":"Indian Constitution at Work","q":"A person whose Fundamental Right has been violated can go directly to the Supreme Court. This is the Court's:","w":"Under Article 32 the Supreme Court can issue writs such as habeas corpus and mandamus to enforce Fundamental Rights. High Courts can also issue writs, under Article 226.","o":["Advisory jurisdiction","Appellate jurisdiction","Special leave jurisdiction","Writ jurisdiction"],"a":[3]},{"id":"n11icw06-9","p":"n11icw06","n":9,"s":"pol","t":"Indian Constitution at Work","q":"Under its advisory jurisdiction, the Supreme Court:","w":"Under Article 143 the President can refer a matter to the Supreme Court for advice. The Court may give its opinion, and the President is not bound to follow it; it helps the government seek legal clarity before acting.","o":["Can be asked by the President for its opinion on a question of public importance or law, but its advice is not binding on the President","Must give advice whenever the Prime Minister asks for it","Advises state governments on all their laws","Hears appeals from High Courts"],"a":[0]},{"id":"n11icw06-10","p":"n11icw06","n":10,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following statements about the High Courts is correct?","w":"High Courts hear appeals from subordinate courts, issue writs and supervise the courts below them. Their decisions can be appealed in the Supreme Court; disputes between states go to the Supreme Court.","o":["Their decisions cannot be appealed against in any court","They are appointed by the state legislatures","They can hear disputes between two states","They can hear appeals from lower courts and issue writs to enforce rights"],"a":[3]},{"id":"n11icw06-11","p":"n11icw06","n":11,"s":"pol","t":"Indian Constitution at Work","q":"\"Public Interest Litigation\" (PIL) means that:","w":"From the late 1970s the Supreme Court allowed any public-spirited person to approach it on behalf of the poor or the public. Even letters and newspaper reports were treated as petitions.","o":["A person or group can go to court on behalf of those whose rights are affected, for an issue of public interest","Only the person whose rights are violated can go to court","Cases are decided by a public vote","Only the government can file cases"],"a":[0]},{"id":"n11icw06-12","p":"n11icw06","n":12,"s":"pol","t":"Indian Constitution at Work","q":"Judicial activism through PIL in India began around:","w":"The Hussainara Khatoon case (1979), about undertrial prisoners, is seen as the beginning. Judges such as P.N. Bhagwati and V.R. Krishna Iyer took the lead in letting the poor reach the court.","o":["1950–1955","1965–1970","1979–1980","2000–2005"],"a":[2]},{"id":"n11icw06-13","p":"n11icw06","n":13,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is a criticism of judicial activism, as discussed in the chapter?","w":"Activism made courts more accessible and democratic, but critics say courts have sometimes entered areas belonging to the executive and legislature, and the extra cases add to their burden.","o":["It has reduced the number of cases in the courts","It has abolished Fundamental Rights","It has stopped the courts from hearing cases of the poor","It has blurred the line between the executive and the judiciary, and has added to the burden on the courts"],"a":[3]},{"id":"n11icw06-14","p":"n11icw06","n":14,"s":"pol","t":"Indian Constitution at Work","q":"The power of the judiciary to examine whether a law is consistent with the Constitution, and to declare it invalid if it is not, is called:","w":"Judicial review lets the Supreme Court and High Courts strike down laws that violate Fundamental Rights or the division of powers between the Centre and the states. The term is not in the Constitution, but the power is.","o":["Judicial review","Judicial activism","Advisory jurisdiction","Original jurisdiction"],"a":[0]},{"id":"n11icw06-15","p":"n11icw06","n":15,"s":"pol","t":"Indian Constitution at Work","q":"In which case did the Supreme Court hold that Parliament cannot amend the \"basic structure\" of the Constitution?","w":"In Kesavananda Bharati (1973) the Court ruled that Parliament can amend any part of the Constitution, but not its basic structure. In Golaknath (1967) it had held that Fundamental Rights could not be amended at all.","o":["Golaknath case, 1967","Kesavananda Bharati case, 1973","Hussainara Khatoon case, 1979","S.R. Bommai case, 1994"],"a":[1]},{"id":"n11icw06-16","p":"n11icw06","n":16,"s":"pol","t":"Indian Constitution at Work","q":"The conflict between the judiciary and Parliament in the 1960s and 1970s was mainly about:","w":"Laws on land reforms and nationalisation clashed with the right to property. Parliament passed amendments, the courts struck some down, and the dispute was settled by the basic structure doctrine and later the removal of property from the Fundamental Rights.","o":["The salaries of judges","Parliament's power to restrict the right to property and amend Fundamental Rights, to carry out land reforms and other policies","The location of the Supreme Court","The language of court proceedings"],"a":[1]},{"id":"n11icw06-17","p":"n11icw06","n":17,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is the correct order of the court system in India, from the highest to the lowest?","w":"India has an integrated judiciary: the Supreme Court at the top, then the High Courts, then district courts, and subordinate courts below them. The decisions of a higher court bind the courts below.","o":["High Court, Supreme Court, District Court, Subordinate Courts","Supreme Court, District Court, High Court, Subordinate Courts","Supreme Court, High Court, District Court, Subordinate Courts","District Court, High Court, Supreme Court, Subordinate Courts"],"a":[2]},{"id":"n11icw06-18","p":"n11icw06","n":18,"s":"pol","t":"Indian Constitution at Work","q":"The Supreme Court can hear an appeal against the judgment of any court or tribunal in India, at its discretion, through:","w":"Under Article 136 the Supreme Court may grant special leave to appeal from any judgment of any court or tribunal, except military tribunals. It is used when a serious question of law or injustice is involved.","o":["A writ of habeas corpus","Special leave to appeal","Advisory jurisdiction","A joint sitting of Parliament"],"a":[1]},{"id":"n11icw06-19","p":"n11icw06","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Why is the Indian judiciary called \"integrated\"?","w":"In the USA there are separate federal and state courts. India has one unified system: the Supreme Court's decisions bind all courts in the country.","o":["Because judges are elected together with legislators","Because it is part of the executive","Because every court can hear every kind of case","Because there is a single hierarchy of courts with the Supreme Court at the top, unlike some federations that have separate federal and state courts"],"a":[3]},{"id":"n11icw06-20","p":"n11icw06","n":20,"s":"pol","t":"Indian Constitution at Work","q":"The decisions of the Supreme Court are binding on all other courts in India. Which article ensures this?","w":"Article 141 says that the law declared by the Supreme Court is binding on all courts within the territory of India. Article 32 is about writs, 136 about special leave and 368 about amendments.","o":["Article 32","Article 136","Article 141","Article 368"],"a":[2]},{"id":"n11icw07-1","p":"n11icw07","n":1,"s":"pol","t":"Indian Constitution at Work","q":"Federalism is a system in which:","w":"In a federation there are at least two sets of government, one for the whole country and one for the regions, each with powers given by the constitution. Disputes between them are usually settled by the judiciary.","o":["All power is held by the central government","Local governments make all laws","There is no written constitution","Power is divided between two levels of government, each with its own area of authority, usually laid down in a written constitution"],"a":[3]},{"id":"n11icw07-2","p":"n11icw07","n":2,"s":"pol","t":"Indian Constitution at Work","q":"The chapter discusses the break-up of which country in 1991 as an example of a federation that failed to hold together?","w":"The USSR broke into fifteen independent countries in 1991. Excessive centralisation and the domination of one region over others are seen as reasons.","o":["Canada","Nigeria","Soviet Union","Switzerland"],"a":[2]},{"id":"n11icw07-3","p":"n11icw07","n":3,"s":"pol","t":"Indian Constitution at Work","q":"Article 1 of the Indian Constitution describes India as:","w":"Article 1 says \"India, that is Bharat, shall be a Union of States.\" The word \"federation\" is not used, which reflects that the states did not come together by agreement and cannot leave the Union.","o":["A union of states","A federation of states","A confederation of states","A unitary state with provinces"],"a":[0]},{"id":"n11icw07-4","p":"n11icw07","n":4,"s":"pol","t":"Indian Constitution at Work","q":"The division of legislative powers between the Union and the states is given in which Schedule of the Constitution?","w":"The Seventh Schedule has three lists: the Union List, the State List and the Concurrent List. The First Schedule lists the states and union territories.","o":["First Schedule","Fourth Schedule","Seventh Schedule","Tenth Schedule"],"a":[2]},{"id":"n11icw07-5","p":"n11icw07","n":5,"s":"pol","t":"Indian Constitution at Work","q":"Defence, foreign affairs, banking and atomic energy are subjects in the:","w":"Subjects of national importance such as defence, foreign affairs, currency, banking and atomic energy are in the Union List, on which only Parliament can make laws.","o":["State List","Concurrent List","Residuary powers","Union List"],"a":[3]},{"id":"n11icw07-6","p":"n11icw07","n":6,"s":"pol","t":"Indian Constitution at Work","q":"Police, agriculture and public health are subjects in the:","w":"The State List has subjects of local or regional importance, such as police, agriculture, local government and public health, on which the states make laws.","o":["State List","Union List","Concurrent List","Residuary powers"],"a":[0]},{"id":"n11icw07-7","p":"n11icw07","n":7,"s":"pol","t":"Indian Constitution at Work","q":"Education, forests and marriage are subjects in the Concurrent List. If a state law on a Concurrent List subject conflicts with a law of Parliament on it, then:","w":"Both Parliament and the states can legislate on Concurrent List subjects, but where the two conflict, the Union law prevails.","o":["The state law prevails","The law of Parliament prevails","Both laws stand cancelled","The Governor decides which law applies"],"a":[1]},{"id":"n11icw07-8","p":"n11icw07","n":8,"s":"pol","t":"Indian Constitution at Work","q":"Which government has the power to make laws on subjects not mentioned in any of the three lists (residuary powers)?","w":"Residuary powers rest with Parliament (Article 248). Matters like cyber law, which did not exist when the lists were made, fall under it.","o":["The state governments","Both together, with the Governor's consent","The Union (Parliament)","The Supreme Court"],"a":[2]},{"id":"n11icw07-9","p":"n11icw07","n":9,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following features shows that the Indian Constitution creates a strong central government?\n1. Parliament can form new states and change the boundaries of existing ones\n2. During an emergency, the federal system can work like a unitary one\n3. The Governor of a state is appointed by the President\n4. The Centre has more important sources of revenue than the states","w":"All four point to a strong Centre. The framers wanted a strong Union to keep a large and diverse country together after Partition and to plan its economic development.","o":["1 and 2 only","2 and 3 only","1, 3 and 4 only","1, 2, 3 and 4"],"a":[3]},{"id":"n11icw07-10","p":"n11icw07","n":10,"s":"pol","t":"Indian Constitution at Work","q":"Under Article 3, Parliament can create a new state or change the boundaries of a state. Which of the following is correct?","w":"The President refers the bill to the state legislature for its views, but Parliament can go ahead whatever the state says. This shows that the states' boundaries are not fixed by agreement.","o":["The consent of the state concerned is required","A referendum in the state is compulsory","The Supreme Court must approve the change","The views of the state legislature are sought, but Parliament is not bound by them"],"a":[3]},{"id":"n11icw07-11","p":"n11icw07","n":11,"s":"pol","t":"Indian Constitution at Work","q":"The role of the Governor has been a source of conflict between the Centre and the states mainly because:","w":"Governors are appointed by the President on the Centre's advice. Their reports recommending President's Rule and their choices when no party has a majority have often been accused of serving the party ruling at the Centre.","o":["The Governor, appointed by the Centre, has been seen as acting on the Centre's instructions, for example in recommending President's Rule","The Governor is elected by the state legislature","The Governor heads the High Court","The Governor controls the state's police directly"],"a":[0]},{"id":"n11icw07-12","p":"n11icw07","n":12,"s":"pol","t":"Indian Constitution at Work","q":"President's Rule in a state is imposed under:","w":"Article 356 allows the President to take over a state's administration if its government cannot be carried on according to the Constitution. Article 352 deals with a national emergency and Article 360 with a financial emergency.","o":["Article 352","Article 356","Article 360","Article 370"],"a":[1]},{"id":"n11icw07-13","p":"n11icw07","n":13,"s":"pol","t":"Indian Constitution at Work","q":"The Supreme Court laid down limits on the use of Article 356, holding that the dismissal of a state government can be reviewed by the courts and that majority must be tested on the floor of the House, in:","w":"In S.R. Bommai v. Union of India (1994) the Court ruled that a government's majority must be tested in the assembly and that President's Rule is open to judicial review. Misuse of Article 356 has since declined.","o":["Kesavananda Bharati case","Golaknath case","S.R. Bommai case","Minerva Mills case"],"a":[2]},{"id":"n11icw07-14","p":"n11icw07","n":14,"s":"pol","t":"Indian Constitution at Work","q":"In 1983 the Central Government appointed a commission to examine Centre–state relations. It was headed by:","w":"The Sarkaria Commission (1983–1988) examined Centre–state relations and recommended, among other things, that Governors be impartial and that Article 356 be used only as a last resort.","o":["Justice R.S. Sarkaria","Justice M.M. Punchhi","K. Santhanam","Balwant Rai Mehta"],"a":[0]},{"id":"n11icw07-15","p":"n11icw07","n":15,"s":"pol","t":"Indian Constitution at Work","q":"Demands for more autonomy for the states, discussed in the chapter, have included which of the following?\n1. More powers and important subjects for the states\n2. Independent sources of revenue and more financial resources\n3. Administrative autonomy, without Central control over state services\n4. Cultural and linguistic autonomy","w":"Parties such as the DMK in Tamil Nadu and the Akali Dal in Punjab, and later several states, have raised demands of all these kinds, including opposition to the imposition of Hindi.","o":["1 and 2 only","1, 2 and 3 only","3 and 4 only","1, 2, 3 and 4"],"a":[3]},{"id":"n11icw07-16","p":"n11icw07","n":16,"s":"pol","t":"Indian Constitution at Work","q":"Disputes between states over sharing river waters, such as the Cauvery, have been dealt with mainly through:","w":"Inter-state river disputes, like the one between Karnataka and Tamil Nadu over the Cauvery, have been referred to tribunals set up under a law of Parliament.","o":["The Election Commission","A national referendum","Water disputes tribunals set up by the Centre","The Finance Commission"],"a":[2]},{"id":"n11icw07-17","p":"n11icw07","n":17,"s":"pol","t":"Indian Constitution at Work","q":"Why does the chapter describe some features of Indian federalism as \"asymmetric\"?","w":"Articles 371 and others give special provisions to states such as Nagaland, Mizoram, Assam and Andhra Pradesh, and to tribal areas. Such asymmetry accommodates regional needs within one framework.","o":["Because all states are treated exactly alike","Because some states and regions have special provisions in the Constitution because of their history and circumstances","Because the Rajya Sabha has equal seats for every state","Because the Union has no special powers"],"a":[1]},{"id":"n11icw07-18","p":"n11icw07","n":18,"s":"pol","t":"Indian Constitution at Work","q":"The reorganisation of states on the basis of language in 1956 followed the report of:","w":"The States Reorganisation Commission's report led to the States Reorganisation Act, 1956, which redrew most state boundaries on linguistic lines. The chapter treats it as a way of accommodating diversity, not a threat to unity.","o":["The States Reorganisation Commission","The Sarkaria Commission","The Finance Commission","The Cabinet Mission"],"a":[0]},{"id":"n11icw07-19","p":"n11icw07","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Which three new states were created in the year 2000?","w":"Chhattisgarh (from Madhya Pradesh), Uttarakhand (from Uttar Pradesh) and Jharkhand (from Bihar) were formed in 2000. Telangana was formed from Andhra Pradesh in 2014.","o":["Telangana, Uttarakhand and Jharkhand","Chhattisgarh, Uttarakhand and Jharkhand","Goa, Mizoram and Arunachal Pradesh","Chhattisgarh, Telangana and Goa"],"a":[1]},{"id":"n11icw07-20","p":"n11icw07","n":20,"s":"pol","t":"Indian Constitution at Work","q":"During a national emergency under Article 352, which of the following can happen?","w":"During a national emergency the federal division of powers can be set aside: Parliament can legislate on State List subjects and the Centre can give directions to the states, so the system works in a unitary way.","o":["Parliament can make laws on subjects in the State List","The states become independent of the Union","The Supreme Court is dissolved","Elections to the Lok Sabha become compulsory every year"],"a":[0]},{"id":"n11icw08-1","p":"n11icw08","n":1,"s":"pol","t":"Indian Constitution at Work","q":"Why does the chapter consider local government important for democracy?","w":"Local government is government at the village and town level. It solves everyday problems quickly and lets ordinary people take part, which deepens democracy.","o":["Because it removes the need for state governments","Because it controls the armed forces","Because it makes laws for the whole country","Because it is government closest to the people, dealing with their everyday problems, and lets them take part directly in decisions"],"a":[3]},{"id":"n11icw08-2","p":"n11icw08","n":2,"s":"pol","t":"Indian Constitution at Work","q":"Elected local self-government bodies were first created in British India in 1882 under:","w":"Lord Ripon's resolution of 1882 introduced elected local bodies, called local boards. Their powers were limited and only a few people could vote.","o":["Lord Curzon","Lord Dalhousie","Lord Ripon","Lord Mountbatten"],"a":[2]},{"id":"n11icw08-3","p":"n11icw08","n":3,"s":"pol","t":"Indian Constitution at Work","q":"At the time of making the Constitution, local government was placed in:","w":"Article 40 directed the state to organise village panchayats, and local government was a State List subject. It got a full constitutional status only with the 73rd and 74th Amendments.","o":["The Fundamental Rights","The Union List","The Fundamental Duties","The Directive Principles of State Policy, as a subject for the states"],"a":[3]},{"id":"n11icw08-4","p":"n11icw08","n":4,"s":"pol","t":"Indian Constitution at Work","q":"Which committee, set up in 1957, recommended a three-tier system of Panchayati Raj?","w":"The Balwant Rai Mehta Committee (1957) recommended elected bodies at the village, block and district levels. Many states then set up Panchayati Raj institutions.","o":["Balwant Rai Mehta Committee","Ashok Mehta Committee","L.M. Singhvi Committee","Sarkaria Commission"],"a":[0]},{"id":"n11icw08-5","p":"n11icw08","n":5,"s":"pol","t":"Indian Constitution at Work","q":"The 73rd and 74th Amendments, which gave constitutional status to local governments, were passed in:","w":"Both were passed in 1992 and came into force in 1993. The 73rd deals with rural local bodies (panchayats) and the 74th with urban local bodies (municipalities).","o":["1985","1989","1992","1996"],"a":[2]},{"id":"n11icw08-6","p":"n11icw08","n":6,"s":"pol","t":"Indian Constitution at Work","q":"Under the 73rd Amendment, the three tiers of Panchayati Raj are at the level of:","w":"The Gram Panchayat works at the village level, the Mandal or Panchayat Samiti at the block level, and the Zilla Parishad at the district level.","o":["Village, block (intermediate) and district","Village, state and union","Ward, city and metropolitan area","Village, tehsil and state"],"a":[0]},{"id":"n11icw08-7","p":"n11icw08","n":7,"s":"pol","t":"Indian Constitution at Work","q":"Which states are allowed not to have the intermediate (block) level of panchayats?","w":"The 73rd Amendment lets very small states, with a population below 20 lakh, skip the intermediate tier, since a two-tier system is enough there.","o":["States with a population below 20 lakh","States with a coastline","States with a High Court","States in the Sixth Schedule only"],"a":[0]},{"id":"n11icw08-8","p":"n11icw08","n":8,"s":"pol","t":"Indian Constitution at Work","q":"Consider the following statements about the 73rd Amendment:\n1. Elections to panchayats must be held every five years.\n2. If a panchayat is dissolved early, elections must be held within six months.\n3. One-third of the seats and of the posts of chairperson are reserved for women.\nWhich of the statements given above are correct?","w":"All three are correct. These provisions ended the practice of states postponing panchayat elections for years, and brought lakhs of women into public life.","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11icw08-9","p":"n11icw08","n":9,"s":"pol","t":"Indian Constitution at Work","q":"Under the 73rd Amendment, reservation for the Scheduled Castes and Scheduled Tribes in panchayats is:","w":"Seats for SCs and STs are reserved in proportion to their population. Reservation for Other Backward Classes is left to the states to decide.","o":["Fixed at one-third in all states","Left entirely to the panchayat","In proportion to their share in the population","Not provided"],"a":[2]},{"id":"n11icw08-10","p":"n11icw08","n":10,"s":"pol","t":"Indian Constitution at Work","q":"Which body conducts elections to the panchayats and municipalities?","w":"Each state has a State Election Commissioner, independent of the state government, to conduct local body elections. The Election Commission of India handles elections to Parliament and state legislatures.","o":["The Election Commission of India","The District Collector","The Governor","The State Election Commission"],"a":[3]},{"id":"n11icw08-11","p":"n11icw08","n":11,"s":"pol","t":"Indian Constitution at Work","q":"The State Finance Commission, set up under the 73rd and 74th Amendments, is meant to:","w":"Every five years the state government must set up a State Finance Commission to examine the financial position of local bodies and recommend how funds should be shared with them.","o":["Review the finances of local bodies and recommend how revenue should be shared between the state and local governments","Prepare the state budget","Audit the accounts of the Centre","Fix the salaries of state ministers"],"a":[0]},{"id":"n11icw08-12","p":"n11icw08","n":12,"s":"pol","t":"Indian Constitution at Work","q":"How many subjects are listed in the Eleventh Schedule for the panchayats?","w":"The Eleventh Schedule lists 29 subjects, such as agriculture, minor irrigation, drinking water and primary education. The state legislature decides how many of them actually go to the panchayats.","o":["18","22","29","35"],"a":[2]},{"id":"n11icw08-13","p":"n11icw08","n":13,"s":"pol","t":"Indian Constitution at Work","q":"How many subjects are listed in the Twelfth Schedule for urban local bodies?","w":"The Twelfth Schedule, added by the 74th Amendment, lists 18 subjects for municipalities, such as urban planning, water supply and public health.","o":["12","18","29","30"],"a":[1]},{"id":"n11icw08-14","p":"n11icw08","n":14,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following are urban local bodies under the 74th Amendment?","w":"The 74th Amendment provides for Nagar Panchayats for areas changing from rural to urban, Municipal Councils for smaller towns and Municipal Corporations for large cities.","o":["Gram Panchayat, Panchayat Samiti and Zilla Parishad","Gram Sabha and Mandal Parishad","Nagar Panchayat, Municipal Council and Municipal Corporation","District Board and Taluk Board"],"a":[2]},{"id":"n11icw08-15","p":"n11icw08","n":15,"s":"pol","t":"Indian Constitution at Work","q":"The Gram Sabha consists of:","w":"The Gram Sabha is the assembly of all voters of the village. It is meant to discuss the panchayat's work and approve plans, making the panchayat accountable to the people.","o":["Only the elected members of the Gram Panchayat","Government officers of the block","Members of the state legislature from the area","All adult voters registered in the electoral roll of the village panchayat area"],"a":[3]},{"id":"n11icw08-16","p":"n11icw08","n":16,"s":"pol","t":"Indian Constitution at Work","q":"The provisions of the 73rd Amendment were extended to the Scheduled (tribal) Areas of several states in 1996 by a law known as:","w":"Many tribal areas were at first kept out of the 73rd Amendment. PESA (1996) extended panchayats to Fifth Schedule areas while respecting traditional customs of managing community resources.","o":["PESA, the Provisions of the Panchayats (Extension to the Scheduled Areas) Act","The Forest Rights Act","The Tribal Autonomy Act","The Gram Nyayalaya Act"],"a":[0]},{"id":"n11icw08-17","p":"n11icw08","n":17,"s":"pol","t":"Indian Constitution at Work","q":"The chapter notes a major weakness in the working of local governments even after the amendments. Which one?","w":"Local bodies raise very little revenue themselves and rely on grants. Many states have also not handed over the 29 subjects and the staff to go with them, so local bodies often remain implementers of schemes.","o":["They have too many funds and too few responsibilities","They depend heavily on state and central grants and have few powers and resources of their own","Their elections are held by the Supreme Court","They have no elected members"],"a":[1]},{"id":"n11icw08-18","p":"n11icw08","n":18,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following was a direct result of the reservation of seats for women in local bodies?","w":"Reserving one-third of seats and chairperson posts for women brought lakhs of women into local politics. Many states have since raised women's reservation in local bodies to half.","o":["The abolition of the Gram Sabha","A large number of women, including many from SC, ST and OBC groups, entering elected local offices","The end of elections in villages","A ban on men contesting"],"a":[1]},{"id":"n11icw08-19","p":"n11icw08","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Which programme of the 1950s, involving people in local development, preceded the creation of Panchayati Raj institutions?","w":"The Community Development Programme (1952) sought people's participation in rural development. Its weaknesses led to the Balwant Rai Mehta Committee and elected Panchayati Raj bodies.","o":["Green Revolution","Community Development Programme","Integrated Rural Development Programme","National Rural Employment Guarantee"],"a":[1]},{"id":"n11icw08-20","p":"n11icw08","n":20,"s":"pol","t":"Indian Constitution at Work","q":"Which Indian leader saw village panchayats as the basis of a truly decentralised democracy, often described as \"gram swaraj\"?","w":"Gandhi wanted power decentralised to self-governing villages. Ambedkar, by contrast, distrusted village politics as a site of caste domination, so the Constitution at first put panchayats only in the Directive Principles.","o":["Mahatma Gandhi","Dr. B.R. Ambedkar","Sardar Patel","Subhas Chandra Bose"],"a":[0]},{"id":"n11icw09-1","p":"n11icw09","n":1,"s":"pol","t":"Indian Constitution at Work","q":"Why does the chapter call the Indian Constitution a \"living document\"?","w":"Like a living being, the Constitution adapts to new needs: through amendments by Parliament and through the way courts read it. Its basic framework has nevertheless stayed the same since 1950.","o":["Because it is rewritten completely after every general election","Because it can be changed by the President alone","Because it has no fixed text","Because it responds to changing situations through amendments and judicial interpretation while keeping its core principles"],"a":[3]},{"id":"n11icw09-2","p":"n11icw09","n":2,"s":"pol","t":"Indian Constitution at Work","q":"The procedure for amending the Indian Constitution is laid down in:","w":"Article 368 gives Parliament the power to amend the Constitution and sets out the procedure. Some provisions can also be changed by an ordinary law, as the Constitution itself allows.","o":["Article 32","Article 356","Article 368","Article 370"],"a":[2]},{"id":"n11icw09-3","p":"n11icw09","n":3,"s":"pol","t":"Indian Constitution at Work","q":"Most amendments under Article 368 require a \"special majority\" in each House of Parliament. This means:","w":"The special majority has two parts: more than half of the House's total strength must support the bill, and the supporters must be at least two-thirds of those present and voting.","o":["A majority of the total membership of the House and at least two-thirds of the members present and voting","A simple majority of members present","Three-fourths of the members present","Unanimous support of the House"],"a":[0]},{"id":"n11icw09-4","p":"n11icw09","n":4,"s":"pol","t":"Indian Constitution at Work","q":"Amendments relating to which of the following also need ratification by the legislatures of at least half of the states?","w":"Provisions that affect the federal structure, such as the lists of powers, the election of the President, the representation of states in Parliament and the powers of the courts, need approval by half the states as well.","o":["The salaries of Members of Parliament","The age of retirement of civil servants","The distribution of powers between the Union and the states, and the representation of states in Parliament","The procedure of Question Hour"],"a":[2]},{"id":"n11icw09-5","p":"n11icw09","n":5,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is NOT part of the amendment procedure in India?","w":"Unlike some countries such as Switzerland, India does not use a referendum for amendments. There is also no separate body for amending the Constitution; Parliament does it.","o":["Special majority in both Houses of Parliament","Ratification by half the states for certain provisions","A referendum in which all voters vote on the amendment","The President's assent"],"a":[2]},{"id":"n11icw09-6","p":"n11icw09","n":6,"s":"pol","t":"Indian Constitution at Work","q":"After an amendment bill is passed by Parliament (and ratified by the states where needed), the President:","w":"Since the 24th Amendment (1971) the President must give assent to a constitutional amendment bill. The President cannot return it or keep it pending.","o":["Has to give assent; there is no option to withhold it or return it","Can send it back for reconsideration like an ordinary bill","Must refer it to the Supreme Court","Can hold a referendum on it"],"a":[0]},{"id":"n11icw09-7","p":"n11icw09","n":7,"s":"pol","t":"Indian Constitution at Work","q":"The chapter groups the many amendments to the Constitution into categories. Which category does an amendment raising the retirement age of High Court judges from 60 to 62 fall into?","w":"Such amendments (here the 15th Amendment, 1963) only clarify or adjust details, such as salaries and retirement ages, without changing basic provisions.","o":["Amendments due to differing interpretations","Amendments through political consensus","Controversial amendments of the Emergency period","Amendments of a technical or administrative nature"],"a":[3]},{"id":"n11icw09-8","p":"n11icw09","n":8,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following amendments are examples of changes made through broad political consensus?\n1. The anti-defection law (52nd Amendment)\n2. Lowering the voting age to 18 (61st Amendment)\n3. The 73rd and 74th Amendments on local governments","w":"The chapter treats all three as amendments that had the support of most parties, reflecting a shared view of what the political system needed.","o":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11icw09-9","p":"n11icw09","n":9,"s":"pol","t":"Indian Constitution at Work","q":"Many amendments between 1970 and 1975 arose from a conflict between Parliament and the judiciary. What was the conflict mainly about?","w":"Parliament wanted to amend Fundamental Rights to carry out land reforms and nationalisation; the courts resisted. Parliament passed amendments to overcome court judgments, and the courts in turn reviewed them.","o":["Differing interpretations of the Constitution, especially on Parliament's power to amend Fundamental Rights such as the right to property","The location of the Supreme Court","The number of judges","The language of the Constitution"],"a":[0]},{"id":"n11icw09-10","p":"n11icw09","n":10,"s":"pol","t":"Indian Constitution at Work","q":"Which amendment, passed during the Emergency, made very wide changes to the Constitution and is often called a \"mini constitution\"?","w":"The 42nd Amendment (1976) changed many parts of the Constitution, including the Preamble, the term of the Lok Sabha and the powers of the courts. The chapter treats the 38th, 39th and 42nd Amendments as the most controversial.","o":["24th Amendment","38th Amendment","42nd Amendment","44th Amendment"],"a":[2]},{"id":"n11icw09-11","p":"n11icw09","n":11,"s":"pol","t":"Indian Constitution at Work","q":"After the Emergency, many changes made by the 42nd Amendment were undone mainly by:","w":"The Janata government's 43rd (1977) and 44th (1978) Amendments reversed many Emergency-era changes and added safeguards, for example on proclaiming a national emergency.","o":["The 43rd and 44th Amendments","The 52nd Amendment","The 61st Amendment","The 73rd Amendment"],"a":[0]},{"id":"n11icw09-12","p":"n11icw09","n":12,"s":"pol","t":"Indian Constitution at Work","q":"The words \"socialist\" and \"secular\" were added to the Preamble by:","w":"The 42nd Amendment (1976) added \"socialist\", \"secular\" and \"integrity\" to the Preamble. The chapter notes that the principles behind them were already part of the Constitution.","o":["The 24th Amendment","The 42nd Amendment","The 44th Amendment","The 86th Amendment"],"a":[1]},{"id":"n11icw09-13","p":"n11icw09","n":13,"s":"pol","t":"Indian Constitution at Work","q":"The \"basic structure\" doctrine, laid down in the Kesavananda Bharati case (1973), means that:","w":"The Court balanced the two sides: Parliament has wide power to amend, but features such as the supremacy of the Constitution, democracy, secularism, federalism and judicial review cannot be destroyed.","o":["Parliament cannot amend the Constitution at all","Only the Supreme Court can amend the Constitution","The states can veto any amendment","Parliament can amend any part of the Constitution, but not in a way that destroys its basic structure"],"a":[3]},{"id":"n11icw09-14","p":"n11icw09","n":14,"s":"pol","t":"Indian Constitution at Work","q":"Who decides what is part of the \"basic structure\" of the Constitution?","w":"The Constitution does not list the basic structure. The courts identify its elements while deciding cases, which gives the judiciary an important role in shaping the Constitution.","o":["Parliament","The judiciary, case by case","The President","The Election Commission"],"a":[1]},{"id":"n11icw09-15","p":"n11icw09","n":15,"s":"pol","t":"Indian Constitution at Work","q":"The chapter says the Constitution has been kept flexible as well as rigid. Which statement best describes this balance?","w":"The framers made some provisions easy to change, while protecting the most important ones with a special majority and, for federal features, the consent of the states. This makes the Constitution adaptable but not easy to tamper with.","o":["Every part can be changed by a simple majority","No part can ever be changed","Some parts can be changed by simple majority, most need a special majority, and federal provisions also need state ratification","Only the Supreme Court can change any part"],"a":[2]},{"id":"n11icw09-16","p":"n11icw09","n":16,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following can be changed by Parliament through a simple majority, without following the special procedure of Article 368?","w":"Under Articles 2 to 4, laws on admitting or forming states and changing boundaries are passed by a simple majority and are not treated as amendments under Article 368.","o":["The Fundamental Rights","The election of the President","The powers of the Supreme Court","The formation of new states and changes in the boundaries of existing states"],"a":[3]},{"id":"n11icw09-17","p":"n11icw09","n":17,"s":"pol","t":"Indian Constitution at Work","q":"The judiciary has contributed to the Constitution being a \"living document\" mainly by:","w":"Courts have widened the meaning of rights, for example reading the right to life to include livelihood, education and a clean environment. Such interpretation keeps the text relevant without formal amendment.","o":["Interpreting its provisions, such as the right to life, in new ways to meet changing needs","Refusing to hear constitutional cases","Electing the members of Parliament","Writing new articles into the Constitution itself"],"a":[0]},{"id":"n11icw09-18","p":"n11icw09","n":18,"s":"pol","t":"Indian Constitution at Work","q":"Which body was appointed by the Government of India in 2000 to review the working of the Constitution?","w":"The Venkatachaliah Commission reviewed the Constitution's working and suggested changes within its basic framework. It was not asked to write a new constitution.","o":["The Sarkaria Commission","The National Commission to Review the Working of the Constitution, headed by Justice M.N. Venkatachaliah","The States Reorganisation Commission","The Law Commission headed by Justice Ranganath Misra"],"a":[1]},{"id":"n11icw09-19","p":"n11icw09","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Why does the chapter say that frequent amendments do not mean the Constitution is weak?","w":"A large number of amendments reflects a constitution that adapts, not one that is weak. The core values and institutions have stayed intact, including after the Emergency-era changes.","o":["Because most amendments only changed the names of states","Because all amendments were struck down by courts","Because amendments are needed only in a dictatorship","Because many amendments were technical, many came from political consensus, and the basic framework survived the controversial ones"],"a":[3]},{"id":"n11icw09-20","p":"n11icw09","n":20,"s":"pol","t":"Indian Constitution at Work","q":"Which feature of the Indian Constitution keeps the balance between the authority of Parliament and the limits placed on it?","w":"Elected representatives can change the Constitution, while the courts ensure the changes do not destroy its foundations. The chapter sees this balance as a mark of political maturity.","o":["The absence of judicial review","Parliament can amend the Constitution, but the judiciary can review amendments against the basic structure","The President's power to dissolve the Supreme Court","The supremacy of the state legislatures"],"a":[1]},{"id":"n11icw10-1","p":"n11icw10","n":1,"s":"pol","t":"Indian Constitution at Work","q":"What does the chapter mean by the \"political philosophy\" of the Constitution?","w":"Studying the philosophy of the Constitution means asking which ideals it is committed to and how its provisions express them, so that we can judge and interpret it.","o":["The personal religious beliefs of its framers","The procedure for amending it","The moral and political values the Constitution stands for, such as freedom, equality, justice and respect for diversity","The list of union territories"],"a":[2]},{"id":"n11icw10-2","p":"n11icw10","n":2,"s":"pol","t":"Indian Constitution at Work","q":"Why does the chapter say we should go back to the Constituent Assembly Debates?","w":"The debates record why particular choices were made. Knowing the reasons helps us interpret provisions and see the Constitution as a moral vision, not just a legal text.","o":["Because they are legally binding on courts in every case","Because they replace the text of the Constitution","Because the Constitution has no Preamble","Because they show the reasons behind the provisions and help us understand and defend the values of the Constitution"],"a":[3]},{"id":"n11icw10-3","p":"n11icw10","n":3,"s":"pol","t":"Indian Constitution at Work","q":"The chapter describes the Constitution as a means of democratic transformation. This means that it:","w":"The Constitution restrains power so that it is not misused, and at the same time gives a peaceful, democratic way to end caste discrimination, inequality and other injustices.","o":["Prevents any change in society","Allows only violent revolution","Limits the power of the government and also empowers it and the people to change unjust social structures peacefully","Gives all power to the judiciary"],"a":[2]},{"id":"n11icw10-4","p":"n11icw10","n":4,"s":"pol","t":"Indian Constitution at Work","q":"The Indian Constitution protected freedom of expression and freedom from arbitrary arrest as fundamental values. This shows its commitment to:","w":"Individual freedom was a demand of the national movement, which had fought censorship and arbitrary arrests under colonial rule. The Constitution made these freedoms fundamental.","o":["Social justice","Federalism","Universal franchise","Individual freedom"],"a":[3]},{"id":"n11icw10-5","p":"n11icw10","n":5,"s":"pol","t":"Indian Constitution at Work","q":"Reservations in legislatures and government jobs for Scheduled Castes and Scheduled Tribes reflect the Constitution's commitment to:","w":"The framers recognised that historical injustice would not end through equal rights alone. Special measures for the most disadvantaged were adopted as part of a commitment to social justice.","o":["Individual freedom alone","Secularism","Social justice","National identity"],"a":[2]},{"id":"n11icw10-6","p":"n11icw10","n":6,"s":"pol","t":"Indian Constitution at Work","q":"The chapter says the Indian Constitution recognises not only individual rights but also the rights of communities. Which provision illustrates this?","w":"The Constitution gives community-based rights, such as the cultural and educational rights of minorities, because the freedom of individuals in India is closely tied to their communities.","o":["The right of religious and linguistic minorities to set up and run their own educational institutions","The right to property","The power of judicial review","The election of the President"],"a":[0]},{"id":"n11icw10-7","p":"n11icw10","n":7,"s":"pol","t":"Indian Constitution at Work","q":"How does the Indian idea of secularism differ from the dominant Western idea, according to the chapter?","w":"In the Western model, state and religion stay out of each other's affairs. In India the state keeps a principled distance: it can, for example, ban untouchability or open temples to all castes, and can aid minority institutions.","o":["Indian secularism requires the state to have an official religion","Indian secularism bans all religious practices","There is no difference at all","The Western idea emphasises mutual exclusion of state and religion, while the Indian idea allows \"principled distance\": the state can intervene in religion to promote equality and can support religious communities"],"a":[3]},{"id":"n11icw10-8","p":"n11icw10","n":8,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is an example of state intervention in religion for the sake of equality, as discussed in the chapter?","w":"The Constitution itself abolishes untouchability and allows laws opening temples to all castes. Such intervention aims to remove caste discrimination within religion.","o":["Declaring Hinduism the state religion","Banning all religious festivals","Abolishing untouchability and permitting laws that throw open Hindu religious institutions to all castes","Allowing only one community to run schools"],"a":[2]},{"id":"n11icw10-9","p":"n11icw10","n":9,"s":"pol","t":"Indian Constitution at Work","q":"By giving every adult the right to vote from the very first election, the Constitution showed its commitment to:","w":"The framers trusted ordinary people with the vote at a time when many were poor and could not read. Universal adult franchise was seen as essential to democracy and national unity.","o":["Universal franchise","Asymmetric federalism","Separate electorates","Indirect democracy only"],"a":[0]},{"id":"n11icw10-10","p":"n11icw10","n":10,"s":"pol","t":"Indian Constitution at Work","q":"\"Asymmetric federalism\" in the Indian Constitution means that:","w":"The Constitution gives special provisions to some states, such as those under Article 371 for the north-eastern states. Treating different regions differently in some respects helped hold diverse regions together.","o":["Every state has exactly the same powers and status","The states have more power than the Union","The Rajya Sabha has equal seats for all states","Some states and regions have special provisions suited to their history and circumstances"],"a":[3]},{"id":"n11icw10-11","p":"n11icw10","n":11,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is one of the \"procedural achievements\" of the Constitution mentioned in the chapter?","w":"The Constitution was made through long debate in which members tried to accommodate different views, and some issues were left open for later. This democratic method is itself an achievement.","o":["It was written by a single leader","It reflects faith in political deliberation and a spirit of accommodation and compromise","It was copied entirely from the British Constitution","It was imposed without discussion"],"a":[1]},{"id":"n11icw10-12","p":"n11icw10","n":12,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following criticisms of the Indian Constitution does the chapter discuss?\n1. It is unwieldy, because it is too long\n2. It is unrepresentative, because the Constituent Assembly was not elected by universal adult franchise\n3. It is an alien document, because many of its provisions were borrowed from Western constitutions","w":"The chapter examines all three and argues each is overstated: length reflects India's needs, the Assembly represented diverse views, and borrowed ideas were adapted to Indian conditions.","o":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11icw10-13","p":"n11icw10","n":13,"s":"pol","t":"Indian Constitution at Work","q":"How does the chapter respond to the criticism that the Constitution is an \"alien document\"?","w":"Borrowing was creative, not blind copying: borrowed institutions were reshaped to suit India. Modern Western ideas had also become part of Indian thinking through the national movement.","o":["It agrees fully that the Constitution is foreign","It says no idea was borrowed from anywhere","It argues that ideas borrowed from other constitutions were adapted to Indian needs, and that a modern Western influence is part of India's own history of modernity","It says the Constitution should be replaced"],"a":[2]},{"id":"n11icw10-14","p":"n11icw10","n":14,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following is one of the limitations of the Constitution identified in the chapter?","w":"The chapter mentions three limitations: a centralised idea of national unity, the neglect of some gender justice issues within the family, and placing some social and economic rights in the Directive Principles instead of the Fundamental Rights.","o":["It does not provide for any Fundamental Rights","It does not deal adequately with some issues of gender justice, particularly within the family","It does not provide for elections","It has no provision for amendment"],"a":[1]},{"id":"n11icw10-15","p":"n11icw10","n":15,"s":"pol","t":"Indian Constitution at Work","q":"Why does the chapter say that keeping social and economic rights in the Directive Principles is a limitation?","w":"Rights such as work and livelihood are in the Directive Principles, which are not justiciable. Many other constitutions of the time made such rights enforceable, which is why the chapter treats this as a limitation.","o":["Because Directive Principles cannot be enforced in courts, so these rights are not guaranteed","Because Directive Principles are not part of the Constitution","Because Directive Principles apply only to minorities","Because Directive Principles were removed in 1976"],"a":[0]},{"id":"n11icw10-16","p":"n11icw10","n":16,"s":"pol","t":"Indian Constitution at Work","q":"Which value of the Constitution is reflected in the fact that a citizen of any religion, caste or region has equal rights and the state does not discriminate among them?","w":"Equal citizenship, without discrimination on grounds of religion, caste, sex or place of birth, binds a diverse people into one nation. The Constitution builds national identity on this rather than on any one religion or language.","o":["Equality and national unity based on equal citizenship","Asymmetric federalism","Separate electorates","Preventive detention"],"a":[0]},{"id":"n11icw10-17","p":"n11icw10","n":17,"s":"pol","t":"Indian Constitution at Work","q":"The chapter says that the Indian Constitution does not demand that people give up their cultural identities to be part of the nation. This shows its:","w":"Indian national identity is meant to coexist with regional, linguistic and religious identities. The Constitution protects these diverse identities while building a shared citizenship.","o":["Respect for diversity","Centralised notion of unity","Rejection of minority rights","Preference for one language"],"a":[0]},{"id":"n11icw10-18","p":"n11icw10","n":18,"s":"pol","t":"Indian Constitution at Work","q":"According to the chapter, what does it mean to say that the Constitution was made through a \"spirit of accommodation\"?","w":"Many provisions, such as those on language and minorities, came out of negotiation and compromise. This spirit gave the Constitution wide acceptance.","o":["That every decision was taken by a vote of one party","That members tried to reach agreement on difficult questions, sometimes by compromise, rather than by imposing a majority view","That the framers avoided all difficult issues","That the British accommodated the Assembly's demands"],"a":[1]},{"id":"n11icw10-19","p":"n11icw10","n":19,"s":"pol","t":"Indian Constitution at Work","q":"Which of the following statements about the Constituent Assembly and the criticism that it was \"unrepresentative\" is supported by the chapter?","w":"The chapter accepts that the Assembly was elected on a limited franchise but argues that its members brought in diverse views, and that the Constitution's acceptance over the years strengthens its claim to represent the people.","o":["The Assembly included only members of one religion","Although members were not elected by universal adult franchise, the Assembly represented a wide range of opinions, and its debates reflect concerns of many sections of society","The Assembly had no members from the provinces","The members were appointed by the British Parliament"],"a":[1]},{"id":"n11icw10-20","p":"n11icw10","n":20,"s":"pol","t":"Indian Constitution at Work","q":"Which pair correctly matches a core feature of the Constitution with an example of it?","w":"Reservations are a means of social justice. Preventive detention limits freedom, an official religion would go against secularism, and limiting votes to graduates would deny universal franchise.","o":["Social justice — Reservations for SCs and STs","Individual freedom — Preventive detention","Secularism — An official state religion","Universal franchise — Voting rights only for graduates"],"a":[0]},{"id":"n11pt01-1","p":"n11pt01","n":1,"s":"pol","t":"Political Theory","q":"According to the chapter, what does political theory mainly deal with?","w":"Political theory examines the values that inform public life, such as freedom, equality, justice, democracy and secularism, and clarifies what they mean and why they matter.","o":["The day-to-day working of political parties only","The election results of different countries","The biographies of political leaders","The ideas and principles that shape constitutions, governments and social life, such as freedom, equality and justice"],"a":[3]},{"id":"n11pt01-2","p":"n11pt01","n":2,"s":"pol","t":"Political Theory","q":"The chapter argues that politics is:","w":"People often see politics as manipulation, but the chapter treats it as the way societies decide on common goals and settle conflicts, through governments and also through citizens' activities and movements.","o":["Only a dirty game of self-interested leaders","Only about what governments do","An important part of social life, concerned with how a society is organised and how collective decisions are made, in which all of us take part","Something ordinary people should avoid"],"a":[2]},{"id":"n11pt01-3","p":"n11pt01","n":3,"s":"pol","t":"Political Theory","q":"Which thinker argued that freedom is a fundamental right of human beings, as mentioned in the chapter?","w":"The chapter mentions Rousseau as having argued that freedom is the fundamental right of human beings, and Marx as having argued that equality is as crucial as freedom.","o":["Jean-Jacques Rousseau","Karl Marx","Mahatma Gandhi","Aristotle"],"a":[0]},{"id":"n11pt01-4","p":"n11pt01","n":4,"s":"pol","t":"Political Theory","q":"Which thinker is mentioned in the chapter as arguing that equality is as important as freedom?","w":"Marx stressed economic equality, arguing that freedom means little without it. Political theory looks at how such thinkers defined key ideas.","o":["John Locke","Thomas Hobbes","Karl Marx","Plato"],"a":[2]},{"id":"n11pt01-5","p":"n11pt01","n":5,"s":"pol","t":"Political Theory","q":"Which Indian leader discussed the meaning of true freedom, or swaraj, in his book Hind Swaraj?","w":"In Hind Swaraj (1909) Gandhi explained swaraj as self-rule, including rule over oneself, not just the end of British rule.","o":["B.R. Ambedkar","Mahatma Gandhi","Jawaharlal Nehru","Rabindranath Tagore"],"a":[1]},{"id":"n11pt01-6","p":"n11pt01","n":6,"s":"pol","t":"Political Theory","q":"The chapter mentions that Dr. B.R. Ambedkar argued that the Scheduled Castes should be treated as:","w":"Ambedkar argued that the Scheduled Castes were a minority who needed special protection. Several of his ideas found a place in the Constitution.","o":["Part of the general category with no special provisions","A separate nation","Voters only in local elections","Minorities entitled to special protection"],"a":[3]},{"id":"n11pt01-7","p":"n11pt01","n":7,"s":"pol","t":"Political Theory","q":"Why does the chapter say we should study political theory?\n1. Because we will all be citizens who vote and take part in public life\n2. Because it helps us think clearly about our own ideas and feelings on political matters\n3. Because it is useful for future politicians, bureaucrats, lawyers and activists","w":"The chapter gives all three reasons. Political theory also encourages us to examine prejudices and to think about issues like justice in a reasoned way.","o":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"a":[3]},{"id":"n11pt01-8","p":"n11pt01","n":8,"s":"pol","t":"Political Theory","q":"When political theory examines what \"freedom\" means in different contexts, it is mainly engaged in:","w":"Political theory tests ideas by asking what they mean in different situations, for example what freedom of expression includes, and whether the arguments behind them hold.","o":["Clarifying the meaning of concepts and examining arguments for and against them","Collecting election data","Writing new laws","Running political parties"],"a":[0]},{"id":"n11pt01-9","p":"n11pt01","n":9,"s":"pol","t":"Political Theory","q":"Questions such as whether parents should be free to stop a daughter's education or decide her marriage show that:","w":"Political ideas are tested in daily situations in families, schools and workplaces, not just in Parliament. This is why political theory is relevant to everyone.","o":["Political theory has no relation to everyday life","Only courts can decide such questions","Questions of freedom and equality arise in our families and everyday lives, not only in government","These matters are fixed by tradition and cannot be debated"],"a":[2]},{"id":"n11pt01-10","p":"n11pt01","n":10,"s":"pol","t":"Political Theory","q":"Which of the following is NOT one of the concepts the chapter says political theory studies?","w":"Political theory studies concepts like freedom, equality, justice, rights, citizenship, nationalism, democracy and secularism. Photosynthesis is a topic of biology.","o":["Freedom","Equality","Justice","Photosynthesis"],"a":[3]},{"id":"n11pt01-11","p":"n11pt01","n":11,"s":"pol","t":"Political Theory","q":"According to the chapter, why can't political ideas be studied like the laws of physics?","w":"Concepts like equality or freedom are not measured in a laboratory. Their meaning is debated, which is why political theory examines arguments and reasons.","o":["Because political ideas have no meaning","Because they are decided only by courts","Because they never change","Because they involve human values and judgements, and people may reasonably interpret them differently in different contexts"],"a":[3]},{"id":"n11pt01-12","p":"n11pt01","n":12,"s":"pol","t":"Political Theory","q":"Which of the following is an example of \"putting political theory into practice\", as discussed in the chapter?","w":"The chapter asks students to apply concepts to real debates, such as how equality of opportunity can be achieved, and to judge arguments on each side.","o":["Memorising definitions of freedom from a textbook","Asking what equality requires in a concrete case, such as whether reservations or special help for some groups is fair","Avoiding all discussion of politics","Counting the number of political parties"],"a":[1]},{"id":"n11pt01-13","p":"n11pt01","n":13,"s":"pol","t":"Political Theory","q":"In a democracy, the meaning of rights and freedoms keeps evolving. What mainly causes this evolution?","w":"Movements, court cases and debates keep widening the meaning of ideals. For example, the right to life in India now includes the right to livelihood and a clean environment.","o":["New problems and struggles that lead people to reinterpret ideals such as freedom and equality","Only changes in technology","Orders of the President","Changes in the weather"],"a":[0]},{"id":"n11pt01-14","p":"n11pt01","n":14,"s":"pol","t":"Political Theory","q":"Political theory traces its origins to thinkers of which ancient civilisation, where Socrates and Plato discussed what justice is?","w":"Socrates and Plato in ancient Athens asked what justice is and what a good society should be like. Their questions are still central to political theory.","o":["Ancient Egypt","Ancient China","Ancient Greece","Mesopotamia"],"a":[2]},{"id":"n11pt01-15","p":"n11pt01","n":15,"s":"pol","t":"Political Theory","q":"Kautilya's Arthashastra, one of the earliest Indian texts on politics, is mainly about:","w":"The Arthashastra discusses how a state should be run: administration, law, economy, diplomacy and war.","o":["Astronomy","Classical dance","Medicine","Statecraft and governance"],"a":[3]},{"id":"n11pt01-16","p":"n11pt01","n":16,"s":"pol","t":"Political Theory","q":"\"Political theory is not just about interpreting the world; it also helps us to examine our own ideas and opinions critically.\" This view suggests that political theory helps citizens to:","w":"Studying arguments about freedom, equality and justice makes us more reflective, able to see other points of view and to defend our own with reasons.","o":["Think about issues logically and test their own beliefs and prejudices","Accept every opinion they hear without question","Avoid voting","Depend entirely on experts"],"a":[0]},{"id":"n11pt01-17","p":"n11pt01","n":17,"s":"pol","t":"Political Theory","q":"The Indian Constitution reflects certain ideals examined by political theory. Which of the following is found in the Preamble?","w":"The Preamble promises justice, liberty, equality and fraternity to all citizens. Political theory helps us understand what these ideals mean and require.","o":["Monarchy and hereditary rule","Justice, liberty, equality and fraternity","A single official religion","Rule by experts only"],"a":[1]},{"id":"n11pt01-18","p":"n11pt01","n":18,"s":"pol","t":"Political Theory","q":"Which of the following best describes the relationship between politics and political theory, according to the chapter?","w":"Political life is shaped by ideas, and ideas are tested in political life. Theory helps citizens and leaders reflect on what goals society should pursue and how.","o":["Political theory is about ideas that guide political life, while politics is the activity of making collective decisions; theory helps us judge and improve politics","They are unrelated","Politics is only about theory, with no practice","Political theory replaces the need for politics"],"a":[0]},{"id":"n11pt01-19","p":"n11pt01","n":19,"s":"pol","t":"Political Theory","q":"Which of these questions is a typical question of political theory?","w":"Political theory asks normative questions about what ought to be, like what is just or fair. Questions of facts and dates belong to other fields of study.","o":["Which party won the most seats in the last election?","How many states does India have?","What is a just distribution of resources in a society?","When is the next session of Parliament?"],"a":[2]},{"id":"n11pt01-20","p":"n11pt01","n":20,"s":"pol","t":"Political Theory","q":"According to the chapter, why are concepts like equality and freedom not \"settled once and for all\"?","w":"Ideas such as freedom and equality are constantly reinterpreted as society changes, for example with new technology or new social movements. Political theory keeps them under examination.","o":["Because no one has ever written about them","Because new situations keep raising new questions about their meaning, which each generation has to debate","Because courts have banned discussion of them","Because they are written only in foreign languages"],"a":[1]},{"id":"n11pt02-1","p":"n11pt02","n":1,"s":"pol","t":"Political Theory","q":"Nelson Mandela's autobiography, discussed in the chapter, is titled:","w":"In Long Walk to Freedom Mandela describes the struggle against apartheid in South Africa and his 27 years in prison. Freedom from Fear is a collection of Aung San Suu Kyi's writings.","o":["Freedom from Fear","The Story of My Experiments with Truth","Long Walk to Freedom","Hind Swaraj"],"a":[2]},{"id":"n11pt02-2","p":"n11pt02","n":2,"s":"pol","t":"Political Theory","q":"\"The only real prison is fear, and the only real freedom is freedom from fear.\" This idea is associated with:","w":"Aung San Suu Kyi of Myanmar, who spent years under house arrest, wrote that freedom means living without fear of what others may think or do.","o":["Aung San Suu Kyi","Nelson Mandela","J.S. Mill","Karl Marx"],"a":[0]},{"id":"n11pt02-3","p":"n11pt02","n":3,"s":"pol","t":"Political Theory","q":"According to the chapter, freedom means:","w":"Freedom has two sides: freedom from unjust constraints, and the opportunity to develop oneself and make choices. Both are needed for a person to be truly free.","o":["The absence of all rules in society","Doing whatever one likes, whatever the effect on others","Only the right to vote","The absence of external constraints, and also the presence of conditions in which people can develop their talents"],"a":[3]},{"id":"n11pt02-4","p":"n11pt02","n":4,"s":"pol","t":"Political Theory","q":"The Indian idea of \"swaraj\", as explained in the chapter, includes:","w":"Swaraj means self-rule. Gandhi stressed that it includes self-control and freedom from the domination of others, not only political independence from Britain.","o":["Only the end of British rule","Rule over the self as well as freedom from external rule","The rule of the strongest","Rule by a king"],"a":[1]},{"id":"n11pt02-5","p":"n11pt02","n":5,"s":"pol","t":"Political Theory","q":"Which of the following can be a source of constraint on freedom, according to the chapter?\n1. Domination and external controls, such as colonial rule\n2. Social inequality, such as the caste system\n3. Extreme economic inequality","w":"Constraints can come from force, from unjust social arrangements and from poverty. A person without resources may not be able to use the freedoms the law gives.","o":["1, 2 and 3","1 and 2 only","2 and 3 only","1 only"],"a":[0]},{"id":"n11pt02-6","p":"n11pt02","n":6,"s":"pol","t":"Political Theory","q":"Why does the chapter say that some constraints are necessary in a society?","w":"In a society where people differ, some limits are needed for peaceful living together. The question is which constraints are justified and which are not.","o":["Because freedom is not valuable","Because governments must control every action","Because people have different ideas and interests, and some rules are needed so that conflicts do not turn violent and everyone's freedom is protected","Because only the rich should be free"],"a":[2]},{"id":"n11pt02-7","p":"n11pt02","n":7,"s":"pol","t":"Political Theory","q":"The \"harm principle\", discussed in the chapter, was put forward by:","w":"In On Liberty, J.S. Mill argued that the only purpose for which power can rightly be used against an individual against his will is to prevent harm to others.","o":["Karl Marx","Mahatma Gandhi","Jean-Jacques Rousseau","John Stuart Mill"],"a":[3]},{"id":"n11pt02-8","p":"n11pt02","n":8,"s":"pol","t":"Political Theory","q":"J.S. Mill distinguished between \"self-regarding\" and \"other-regarding\" actions. Which statement correctly reflects his view?","w":"For Mill, the state may step in only where an action causes harm to others. Even then, minor harm may call only for social disapproval, not legal punishment.","o":["The state should control both kinds of actions equally","Self-regarding actions, which affect only the person concerned, should be free from outside interference; other-regarding actions that harm others can be restricted","Other-regarding actions should never be restricted","Only religious authorities should decide on self-regarding actions"],"a":[1]},{"id":"n11pt02-9","p":"n11pt02","n":9,"s":"pol","t":"Political Theory","q":"According to Mill, for a minor harm caused by an action (not a serious harm), the right response is:","w":"Mill reserved legal punishment for serious harm. Smaller annoyances should be met by social disapproval, so that the power of the state is not used too readily.","o":["Imprisonment","Death penalty","Social disapproval, not the force of law","Banning the person from society permanently"],"a":[2]},{"id":"n11pt02-10","p":"n11pt02","n":10,"s":"pol","t":"Political Theory","q":"\"Negative liberty\", as explained in the chapter, refers to:","w":"Negative liberty is \"freedom from\" interference: a protected zone where the individual can act as he or she wishes. The chapter asks how big this zone should be.","o":["An area of personal life in which no external authority can interfere","The freedom to harm others","The absence of any rights","The state's duty to provide food and shelter"],"a":[0]},{"id":"n11pt02-11","p":"n11pt02","n":11,"s":"pol","t":"Political Theory","q":"\"Positive liberty\" is concerned mainly with:","w":"Positive liberty is \"freedom to\": the ability to realise one's potential. It often needs the state and society to provide opportunities and remove obstacles.","o":["Keeping the state out of all areas of life","Freedom from all laws","The freedom of the rich only","Creating enabling conditions, such as education and health, that allow people to develop and to take part in society"],"a":[3]},{"id":"n11pt02-12","p":"n11pt02","n":12,"s":"pol","t":"Political Theory","q":"Which of the following is an example of a positive conception of liberty?","w":"Providing education creates the conditions for freedom. The first option is about non-interference, which relates to negative liberty.","o":["The state staying out of a person's choice of clothes","The state providing free and compulsory education so that every child can develop","Abolishing all taxes","Banning all newspapers"],"a":[1]},{"id":"n11pt02-13","p":"n11pt02","n":13,"s":"pol","t":"Political Theory","q":"Which of the following works is mentioned in the chapter as an example of a book that was banned in India because some groups were offended by it?","w":"Salman Rushdie's The Satanic Verses was banned in India in 1988 after protests. The chapter uses such bans to discuss the limits of freedom of expression.","o":["Discovery of India","The Satanic Verses","Hind Swaraj","Long Walk to Freedom"],"a":[1]},{"id":"n11pt02-14","p":"n11pt02","n":14,"s":"pol","t":"Political Theory","q":"Which of the following is NOT one of the reasons J.S. Mill gave for protecting freedom of expression, even for ideas that seem false?","w":"Mill argued against silencing opinions. His reasons include the truth in every idea, the value of debate and the chance that accepted views are wrong. Option 3 is the opposite of his position.","o":["No idea is completely false; most have some element of truth","Truth emerges from the conflict of opposing views","The state must decide which ideas are true and silence the rest","What is accepted as true today may later be shown to be false"],"a":[2]},{"id":"n11pt02-15","p":"n11pt02","n":15,"s":"pol","t":"Political Theory","q":"The chapter says that bans on books or films are often a \"short-term solution\". Why?","w":"Banning may calm a protest for a while, but it does not address the underlying disagreement, and it sets a precedent for silencing views. The chapter asks students to weigh this carefully.","o":["Because the issue that caused offence is usually not resolved by banning, and bans can harm freedom of expression","Because bans are never legal","Because books cannot be banned in a democracy","Because films are not covered by freedom of expression"],"a":[0]},{"id":"n11pt02-16","p":"n11pt02","n":16,"s":"pol","t":"Political Theory","q":"Under the Indian Constitution, freedom of speech and expression is:","w":"Article 19 guarantees freedom of speech and expression, but the state can impose reasonable restrictions on specified grounds. The debate is about what counts as reasonable.","o":["Absolute, with no restrictions possible","Not a Fundamental Right","Available only to journalists","A Fundamental Right subject to reasonable restrictions, such as for public order, decency or the security of the state"],"a":[3]},{"id":"n11pt02-17","p":"n11pt02","n":17,"s":"pol","t":"Political Theory","q":"Which idea is central to liberalism, as described in the chapter?","w":"Liberals value individual freedom and tolerate opinions and lifestyles they may not share. Modern liberals also accept a role for the state in removing obstacles to freedom.","o":["The group always matters more than the individual","Tradition must never be questioned","Individual liberty and tolerance of different views, even ones we disagree with","Only the state can decide what is good for each person"],"a":[2]},{"id":"n11pt02-18","p":"n11pt02","n":18,"s":"pol","t":"Political Theory","q":"Why does the chapter say that freedom is valuable?","w":"Freedom lets individuals develop their talents, judgement and creativity and lead lives they value. A free society also benefits from the variety of ideas it allows.","o":["Because it allows people to develop their creativity and capacities, and to make their own choices","Because it lets the powerful rule others","Because it ends the need for laws","Because it makes everyone think alike"],"a":[0]},{"id":"n11pt02-19","p":"n11pt02","n":19,"s":"pol","t":"Political Theory","q":"\"Freedom does not mean only the absence of constraints; it also requires the ability to make choices.\" Which situation best illustrates the second part of this statement?","w":"The poor student faces no legal ban but still lacks the means to exercise the freedom. This is why freedom also depends on social and economic conditions.","o":["A person with no legal restriction on travel","A poor person who is legally free to study but cannot afford school fees","A person forbidden to speak by law","A citizen voting in an election"],"a":[1]},{"id":"n11pt02-20","p":"n11pt02","n":20,"s":"pol","t":"Political Theory","q":"Which of the following constraints would most people consider justified, in the light of the chapter's discussion?","w":"Drunken driving endangers others, so restricting it fits the harm principle. The other options restrict people unfairly or for no good reason and would be unjust constraints.","o":["A law that forbids women from owning property","A ban on a peaceful protest because the government dislikes it","A rule that people of certain castes cannot enter public places","A law against driving under the influence of alcohol, because it can seriously harm others"],"a":[3]},{"id":"n11pt03-1","p":"n11pt03","n":1,"s":"pol","t":"Political Theory","q":"The slogan \"liberty, equality and fraternity\" is associated with which historic event?","w":"French revolutionaries raised this slogan against the privileges of the aristocracy and monarchy in 1789. The chapter uses it to show how equality became a powerful political ideal.","o":["The American Civil War","The French Revolution","The Russian Revolution","The Industrial Revolution"],"a":[1]},{"id":"n11pt03-2","p":"n11pt03","n":2,"s":"pol","t":"Political Theory","q":"Which statement best expresses the idea of equality discussed in the chapter?","w":"Equality does not mean uniformity. It means equal respect and equal rights, and removing differences that come from unjust social arrangements rather than from people's own choices or efforts.","o":["Everyone must be treated identically in every situation","Everyone must earn exactly the same income","There should be no differences of any kind between people","All human beings deserve equal consideration and respect because of their common humanity, and no one should be denied rights or opportunities because of birth or social position"],"a":[3]},{"id":"n11pt03-3","p":"n11pt03","n":3,"s":"pol","t":"Political Theory","q":"Inequalities that arise because people have different abilities and talents are called natural inequalities. Inequalities created by society, such as those based on caste or gender, are called:","w":"Socially produced inequalities come from unequal opportunities or from exploitation and discrimination. The chapter notes that many inequalities once called \"natural\" were in fact produced by society.","o":["Socially produced inequalities","Natural inequalities","Biological inequalities","Accidental inequalities"],"a":[0]},{"id":"n11pt03-4","p":"n11pt03","n":4,"s":"pol","t":"Political Theory","q":"Equality of opportunity means that:","w":"The concept focuses on fair starting points: access to education, health care and jobs. People may then reach different results, but not because some were denied the chance.","o":["Everyone must end up with the same results","Only the talented should get education","All people should have the same chances to develop their talents and pursue their goals, and differences in outcome should not come from unequal chances","Only men should compete for jobs"],"a":[2]},{"id":"n11pt03-5","p":"n11pt03","n":5,"s":"pol","t":"Political Theory","q":"Granting equal citizenship, with equal rights to vote, express views and form associations, is an example of:","w":"Political equality means equal civil and political rights for all citizens. The chapter notes it is necessary but not enough, since social and economic inequality may remain.","o":["Economic equality","Social equality","Political equality","Natural equality"],"a":[2]},{"id":"n11pt03-6","p":"n11pt03","n":6,"s":"pol","t":"Political Theory","q":"Which of the following is an aspect of social equality, as discussed in the chapter?","w":"Social equality means equal opportunities for all groups, which needs basic goods for everyone and an end to discrimination in social life, such as unequal treatment of women.","o":["Ensuring that all have adequate access to basic goods like health care, education and food, and removing discrimination based on caste or gender","Every citizen having one vote","All industries being owned by the state","Fixing equal salaries for all jobs"],"a":[0]},{"id":"n11pt03-7","p":"n11pt03","n":7,"s":"pol","t":"Political Theory","q":"Economic equality, according to the chapter, is mainly about:","w":"Complete economic equality is rarely sought. Democracies try to reduce extreme inequality through taxation, welfare and equal opportunities, so that wealth gaps do not become permanent.","o":["Abolishing all private property immediately","Everyone having exactly the same wealth","Equal voting rights","Reducing the gap between the rich and the poor, and ensuring that no one lacks basic needs"],"a":[3]},{"id":"n11pt03-8","p":"n11pt03","n":8,"s":"pol","t":"Political Theory","q":"Which ideology sees private ownership of important economic resources, such as land and industry, as the main cause of inequality?","w":"Marx argued that those who own the means of production also gain social and political power. Marxists therefore favour public ownership of key resources.","o":["Liberalism","Marxism","Feminism","Anarchism"],"a":[1]},{"id":"n11pt03-9","p":"n11pt03","n":9,"s":"pol","t":"Political Theory","q":"Which ideology, according to the chapter, accepts competition as the fairest and most efficient way of distributing resources, provided there is equality of opportunity?","w":"Liberals accept inequality of outcome if it results from fair competition. They also want political, social and economic inequalities kept separate so that wealth does not buy political power.","o":["Marxism","Socialism","Feminism","Liberalism"],"a":[3]},{"id":"n11pt03-10","p":"n11pt03","n":10,"s":"pol","t":"Political Theory","q":"Feminism, as described in the chapter, stands for:","w":"Feminists challenge patriarchy, a social system that values men more than women and gives them power over women. They distinguish between sex (biological) and gender (social roles).","o":["The superiority of women over men","Equal rights for men and women, and the end of patriarchy","Separate electorates for women","Abolishing the family"],"a":[1]},{"id":"n11pt03-11","p":"n11pt03","n":11,"s":"pol","t":"Political Theory","q":"Feminists distinguish between \"sex\" and \"gender\". What does \"gender\" refer to?","w":"Sex refers to biological differences. Gender refers to roles that society assigns, such as assuming that only women should do housework, which feminists argue can and should change.","o":["Socially defined roles and expectations for men and women","Biological differences between men and women","The number of women in Parliament","Inherited wealth"],"a":[0]},{"id":"n11pt03-12","p":"n11pt03","n":12,"s":"pol","t":"Political Theory","q":"Ram Manohar Lohia identified five kinds of inequality that must be fought together. Which of the following was NOT one of them?","w":"Lohia named inequality between men and women, based on skin colour, caste, the colonial rule of some countries over others, and economic inequality. Blood groups were not part of his list.","o":["Inequality between men and women","Inequality based on caste","Inequality between people with different blood groups","Inequality based on skin colour"],"a":[2]},{"id":"n11pt03-13","p":"n11pt03","n":13,"s":"pol","t":"Political Theory","q":"Lohia added two more revolutions to the fight against five inequalities, calling the whole struggle \"Sapta Kranti\" (seven revolutions). The two were:","w":"The two added revolutions were for civil liberties, against unjust intrusion into private life, and for non-violence as the means of struggle. Lohia argued that all seven revolutions should go on together.","o":["Civil liberties against interference in private life, and non-violence","Industrialisation and urbanisation","Free trade and globalisation","Monarchy and religion"],"a":[0]},{"id":"n11pt03-14","p":"n11pt03","n":14,"s":"pol","t":"Political Theory","q":"Removing laws that discriminate on the basis of caste, religion or gender, so that everyone is equal before the law, is called:","w":"Formal equality removes legal barriers and privileges. The Indian Constitution, for example, prohibits discrimination and abolishes untouchability, but formal equality alone does not end social inequality.","o":["Affirmative action","Differential treatment","Reservations","Establishing formal equality"],"a":[3]},{"id":"n11pt03-15","p":"n11pt03","n":15,"s":"pol","t":"Political Theory","q":"Providing ramps for people with disabilities so that they can enter public buildings is an example of:","w":"Treating people differently can be needed to make them truly equal. Ramps, or special arrangements for women's safety at night, help people with different needs enjoy equal access.","o":["Formal equality only","Equality through differential treatment","Natural inequality","Economic equality"],"a":[1]},{"id":"n11pt03-16","p":"n11pt03","n":16,"s":"pol","t":"Political Theory","q":"Policies such as reservations in education and jobs for disadvantaged groups are known as:","w":"Affirmative action aims to correct the effects of past discrimination by giving special opportunities to disadvantaged groups. The chapter notes the debate about whether such policies should be permanent.","o":["Laissez-faire","Formal equality","Affirmative action","Natural selection"],"a":[2]},{"id":"n11pt03-17","p":"n11pt03","n":17,"s":"pol","t":"Political Theory","q":"Which of the following is an argument against reservations that the chapter discusses?","w":"The chapter presents arguments on both sides: supporters see reservations as needed to correct deep social inequality, while critics raise concerns about fairness and argue for limits. Students are asked to weigh both.","o":["Reservations make the Constitution unwritten","Reservations abolish elections","Reservations are given only to the rich","Reservations, critics say, may be unfair to others and should be temporary, and some argue they should be based on economic need"],"a":[3]},{"id":"n11pt03-18","p":"n11pt03","n":18,"s":"pol","t":"Political Theory","q":"Why does the chapter say that political equality alone is not enough?","w":"Formal political rights mean little if some people lack education, resources or freedom from social domination. That is why social and economic equality are also needed.","o":["Because people with equal votes may still be very unequal in wealth, education and social status, which affects their real power","Because elections are not held regularly","Because political equality is not part of the Constitution","Because voting is optional"],"a":[0]},{"id":"n11pt03-19","p":"n11pt03","n":19,"s":"pol","t":"Political Theory","q":"Which of the following statements reflects the socialist view of equality as described in the chapter?","w":"Socialists believe the market produces unfair inequality and that the state must act to reduce it. In India, socialists also linked economic inequality with caste and other social hierarchies.","o":["The market alone will remove all inequality","Inequality should be reduced through government action, such as public provision of education and health care and control of key resources","Inequality is natural and should not be touched","Only political equality matters"],"a":[1]},{"id":"n11pt03-20","p":"n11pt03","n":20,"s":"pol","t":"Political Theory","q":"A society where some people cannot enter certain public places because of their birth violates which kind of equality most directly?","w":"Denying access to public places because of birth, as under untouchability, is a denial of social equality and equal dignity. The Indian Constitution forbids it.","o":["Economic equality","Natural equality","Social equality","International equality"],"a":[2]},{"id":"n11pt04-1","p":"n11pt04","n":1,"s":"pol","t":"Political Theory","q":"In Plato's Republic, discussed in the chapter, Socrates argues with young friends about whether it is better to be just or unjust. What is Socrates' view?","w":"Glaucon and others argued that the unjust seem to prosper. Socrates replied that justice benefits everyone in the long run, and that a just state serves the good of all its members.","o":["Unjust people are always happier","Justice is only what benefits the strong","Justice is good for everyone in the long run, because it involves the well-being of all people, not only one's own","Justice does not matter in politics"],"a":[2]},{"id":"n11pt04-2","p":"n11pt04","n":2,"s":"pol","t":"Political Theory","q":"The German philosopher Immanuel Kant, mentioned in the chapter, argued that:","w":"For Kant, human dignity means each person deserves equal respect. If all persons have dignity, justice requires that each gets the chance to pursue his or her goals.","o":["Only rulers have dignity","Every human being possesses dignity and deserves to be treated as an end, with the opportunity to develop his or her talents","Justice means obeying the strongest","Inequality is natural and good"],"a":[1]},{"id":"n11pt04-3","p":"n11pt04","n":3,"s":"pol","t":"Political Theory","q":"The ancient Chinese philosopher who argued that rulers should punish wrong-doers and reward the virtuous is:","w":"The chapter notes that Confucius linked justice to good government that punishes wrongs and rewards virtue. In ancient India, justice was linked to dharma and maintaining a just social order.","o":["Plato","Kant","Lao Tzu","Confucius"],"a":[3]},{"id":"n11pt04-4","p":"n11pt04","n":4,"s":"pol","t":"Political Theory","q":"The principle that people should be rewarded according to the effort and skill they put into their work is called:","w":"Proportionate justice means rewards proportional to effort and skill, for example a surgeon earning more than a helper. It works alongside equal treatment and special care for those with special needs.","o":["Proportionate justice","Equal treatment for equals","Recognition of special needs","Natural inequality"],"a":[0]},{"id":"n11pt04-5","p":"n11pt04","n":5,"s":"pol","t":"Political Theory","q":"\"People with the same characteristics should be treated in the same way; they should not be discriminated against because of caste, religion or gender.\" This principle is called:","w":"Equal treatment for equals means equal rights and equal respect for people who are equal in relevant ways, such as men and women doing the same work getting the same pay.","o":["Proportionate justice","Equal treatment for equals","Veil of ignorance","Laissez-faire"],"a":[1]},{"id":"n11pt04-6","p":"n11pt04","n":6,"s":"pol","t":"Political Theory","q":"Giving special facilities to people with disabilities, or to those who have been deprived of opportunities, reflects which principle of justice?","w":"People with special needs or who have suffered disadvantage may need extra help to have a fair chance. Reservations for SCs and STs are justified partly on this principle.","o":["Equal treatment for equals only","The harm principle","Free market justice","Recognition of special needs"],"a":[3]},{"id":"n11pt04-7","p":"n11pt04","n":7,"s":"pol","t":"Political Theory","q":"John Rawls, discussed in the chapter, proposed thinking about a just society from behind a:","w":"Behind a veil of ignorance, people decide the rules of society without knowing what position they will occupy in it: rich or poor, healthy or sick. Rawls argued they would then choose fair rules.","o":["Veil of ignorance","Curtain of wealth","Wall of tradition","Shield of power"],"a":[0]},{"id":"n11pt04-8","p":"n11pt04","n":8,"s":"pol","t":"Political Theory","q":"According to Rawls, people behind the veil of ignorance would choose rules that:","w":"Not knowing whether they will be well-off or badly off, rational people would protect themselves by making sure the worst-off are as well placed as possible. Rawls saw this as both rational and fair.","o":["Benefit the richest","Abolish all private property","Improve the position of the worst-off members of society, since they themselves might be among them","Favour their own caste or religion"],"a":[2]},{"id":"n11pt04-9","p":"n11pt04","n":9,"s":"pol","t":"Political Theory","q":"Rawls argued that choosing just rules behind the veil of ignorance does not require people to be unusually generous. Why?","w":"Rawls's point is that fairness follows from rational self-interest under uncertainty. That is what makes his theory persuasive to people who do not share the same moral views.","o":["Because people are naturally selfless","Because the state forces them to be generous","Because it is rational: anyone could end up among the disadvantaged, so protecting them is in everyone's interest","Because religion requires it"],"a":[2]},{"id":"n11pt04-10","p":"n11pt04","n":10,"s":"pol","t":"Political Theory","q":"Which of the following is an example of a measure taken in India to promote social justice?","w":"Land reforms tried to give land to the tiller and break the power of big landlords, and reservations aim to give fair opportunities to historically disadvantaged groups.","o":["Abolishing elections","Removing the Fundamental Rights","Banning all private schools","Land reforms and reservations for SCs, STs and backward classes"],"a":[3]},{"id":"n11pt04-11","p":"n11pt04","n":11,"s":"pol","t":"Political Theory","q":"Social justice, as discussed in the chapter, is mainly about:","w":"Social justice concerns the just distribution of resources and opportunities among people, which may require reducing inequality and ensuring basic needs for all.","o":["Punishing criminals","A fair distribution of goods, opportunities and rights in society, so that people can live with dignity","Equal marks in examinations","Following ancient customs"],"a":[1]},{"id":"n11pt04-12","p":"n11pt04","n":12,"s":"pol","t":"Political Theory","q":"Supporters of the free market, as described in the chapter, argue that:","w":"Free-market supporters say open competition rewards ability and gives consumers choice. Many accept that the state should provide a basic minimum, such as primary health care, for those in need.","o":["Markets reward talent and effort, allow choice and are efficient, and the state should only ensure a basic minimum","The state should own all industries","Markets always produce equal outcomes","Free markets need no laws at all"],"a":[0]},{"id":"n11pt04-13","p":"n11pt04","n":13,"s":"pol","t":"Political Theory","q":"Critics of an unregulated free market argue that:","w":"Those who start with wealth, education and contacts have an advantage in the market. Without state action, the poor may be left without access to basic goods, which is why critics favour intervention.","o":["Markets never produce goods","Markets lower all prices to zero","Markets are always fair to everyone","Markets tend to favour those who already have resources, and may not provide basic services like health and education to the poor"],"a":[3]},{"id":"n11pt04-14","p":"n11pt04","n":14,"s":"pol","t":"Political Theory","q":"Which of the following is generally accepted, in the chapter's discussion, as part of ensuring social justice?","w":"There is wide agreement that a just society must ensure a minimum standard of living for all, even if people disagree on how far equality should go beyond that.","o":["That every person gets exactly the same income","That everyone's basic needs, such as adequate food, housing, health care, safe drinking water and education, are met","That the state controls all private property","That the market alone decides who gets education"],"a":[1]},{"id":"n11pt04-15","p":"n11pt04","n":15,"s":"pol","t":"Political Theory","q":"Why does the chapter say that all three principles of justice (equal treatment, proportionate reward and special needs) have to be balanced?","w":"Equal treatment alone might ignore people's different efforts or needs; proportionate reward alone might ignore deprivation. A just society combines them sensibly.","o":["Because only one of them is ever valid","Because courts refuse to apply them","Because pushing any one too far can conflict with the others, so a fair society must weigh them together","Because they apply only in Western countries"],"a":[2]},{"id":"n11pt04-16","p":"n11pt04","n":16,"s":"pol","t":"Political Theory","q":"In the context of social justice, the idea that the state should intervene to make sure that people's basic needs are met is associated with:","w":"Supporters of state intervention argue that without it the poor would remain deprived. They support public provision of education, health care and food security.","o":["Those who favour state intervention to reduce inequality","Those who favour an unregulated market with no state role","Those who oppose all government","Those who believe inequality is natural and good"],"a":[0]},{"id":"n11pt04-17","p":"n11pt04","n":17,"s":"pol","t":"Political Theory","q":"The idea that justice involves giving each person what is due to him or her has been understood differently over time. In ancient Indian society, justice was associated with:","w":"The chapter notes that in ancient India justice was linked to dharma, and that rulers were expected to uphold a just social order. Modern ideas of justice emphasise equality and dignity.","o":["The free market","Universal adult franchise","Rawls's veil of ignorance","Dharma and maintaining a just social order"],"a":[3]},{"id":"n11pt04-18","p":"n11pt04","n":18,"s":"pol","t":"Political Theory","q":"Which of the following situations would be considered unjust from the point of view of \"equal treatment for equals\"?","w":"Equal work deserves equal pay. Paying women less for the same work treats equals unequally because of gender.","o":["Paying more to a person who works longer hours","Building ramps for wheelchair users","Paying a woman less than a man for doing the same work","Giving scholarships to poor students"],"a":[2]},{"id":"n11pt04-19","p":"n11pt04","n":19,"s":"pol","t":"Political Theory","q":"Rawls's book that put forward the theory of justice as fairness is:","w":"A Theory of Justice (1971) is Rawls's major work. On Liberty is by J.S. Mill, The Republic by Plato and Das Kapital by Karl Marx.","o":["On Liberty","A Theory of Justice","The Republic","Das Kapital"],"a":[1]},{"id":"n11pt04-20","p":"n11pt04","n":20,"s":"pol","t":"Political Theory","q":"Why do the claims of social justice often require some redistribution of resources?","w":"Inequalities passed down through generations, like those caused by caste or landlessness, mean that formal equality is not enough. Redistribution, through measures like land reforms, helps level the field.","o":["Because existing inequalities, often the result of past injustice, prevent some people from having a fair chance to live with dignity","Because all property is illegal","Because markets do not exist","Because justice means everyone has the same income"],"a":[0]},{"id":"n11pt05-1","p":"n11pt05","n":1,"s":"pol","t":"Political Theory","q":"According to the chapter, a right is best described as:","w":"Rights are claims backed by reasons that society accepts as valid, such as the need for dignity, freedom or well-being. Not every wish, like wanting a particular dress, is a right.","o":["A justified claim or entitlement that society recognises as necessary for a life of dignity and well-being","Anything a person wants","A privilege given only to the rich","An order issued by a ruler"],"a":[0]},{"id":"n11pt05-2","p":"n11pt05","n":2,"s":"pol","t":"Political Theory","q":"In the seventeenth and eighteenth centuries, political theorists argued that rights are given to people by nature or God and cannot be taken away. These are called:","w":"Natural rights were held to exist before any government. Thinkers of that time listed life, liberty and property as natural rights that rulers had no power to violate.","o":["Legal rights","Cultural rights","Natural rights","Economic rights"],"a":[2]},{"id":"n11pt05-3","p":"n11pt05","n":3,"s":"pol","t":"Political Theory","q":"Which three rights were commonly listed as natural rights by these early theorists?","w":"Life, liberty and property were seen as inalienable natural rights. Later, the idea of human rights widened the list to include social and economic needs.","o":["Education, health and work","Life, liberty and property","Vote, contest elections and form parties","Language, culture and religion"],"a":[1]},{"id":"n11pt05-4","p":"n11pt05","n":4,"s":"pol","t":"Political Theory","q":"The Universal Declaration of Human Rights was adopted by the United Nations in:","w":"The UN General Assembly adopted the Universal Declaration of Human Rights on 10 December 1948. It recognises rights that belong to all human beings, irrespective of nationality, race or gender.","o":["1919","1935","1945","1948"],"a":[3]},{"id":"n11pt05-5","p":"n11pt05","n":5,"s":"pol","t":"Political Theory","q":"The idea of \"human rights\", as discussed in the chapter, is based on the belief that:","w":"Human rights are universal. They have been used by oppressed groups around the world to challenge discrimination and demand equal treatment.","o":["Only citizens of rich countries have rights","Rights depend on one's caste or religion","Rights exist only if a king grants them","All human beings, simply by being human, are entitled to certain rights and should be treated with dignity"],"a":[3]},{"id":"n11pt05-6","p":"n11pt05","n":6,"s":"pol","t":"Political Theory","q":"Rights that are written in the Constitution or recognised in laws of the state, so that they can be enforced, are called:","w":"Legal recognition gives rights a firm basis: courts can enforce them. The Indian Constitution, for example, lists Fundamental Rights that citizens can enforce in the courts.","o":["Natural rights","Legal rights","Moral claims only","Customary privileges"],"a":[1]},{"id":"n11pt05-7","p":"n11pt05","n":7,"s":"pol","t":"Political Theory","q":"The right to vote, the right to contest elections and the right to form political parties are examples of:","w":"Political rights let citizens take part in the political process. They are usually supported by civil liberties such as freedom of speech and the right to a fair trial.","o":["Cultural rights","Economic rights","Political rights","Natural rights only"],"a":[2]},{"id":"n11pt05-8","p":"n11pt05","n":8,"s":"pol","t":"Political Theory","q":"Economic rights, according to the chapter, are rights related to:","w":"Political rights mean little without basic economic security. Many democracies provide for minimum wages, work schemes, food security or unemployment relief.","o":["Meeting basic needs like food, shelter, clothing and health, and a decent livelihood","Voting in elections","Using one's mother tongue","Practising one's religion"],"a":[0]},{"id":"n11pt05-9","p":"n11pt05","n":9,"s":"pol","t":"Political Theory","q":"The right of minorities to be educated in their own language and to preserve their own culture is an example of:","w":"Cultural rights recognise that people's identities are tied to their language and culture. Many democracies accept such rights to protect minority groups.","o":["Political rights","Cultural rights","Economic rights","Natural rights only"],"a":[1]},{"id":"n11pt05-10","p":"n11pt05","n":10,"s":"pol","t":"Political Theory","q":"\"Rights not only place obligations on the state; they also place obligations on us.\" Which of the following is an example of such an obligation of the individual?","w":"If I claim freedom of speech, I must accept the same freedom for others. Rights come with responsibilities: to respect others' rights and to care for common goods.","o":["Respecting the rights of others, even when we disagree with them","Ignoring the law when it is inconvenient","Taking away others' freedom of speech","Using public resources only for oneself"],"a":[0]},{"id":"n11pt05-11","p":"n11pt05","n":11,"s":"pol","t":"Political Theory","q":"Why does the chapter say rights place an obligation on us to think about future generations?","w":"The environment we leave behind will shape the rights of future generations to a healthy life. This responsibility is especially clear in debates about pollution and climate change.","o":["Because future generations vote today","Because the Constitution says so in Article 21 only","Because rights end after one generation","Because using resources like air, water and forests carelessly would harm the rights of people who come after us"],"a":[3]},{"id":"n11pt05-12","p":"n11pt05","n":12,"s":"pol","t":"Political Theory","q":"Why does the chapter say that rights often need to be balanced against each other?","w":"A journalist's freedom to report may clash with a person's privacy. Democracies try to balance such rights, often through courts, instead of allowing one to wipe out the other.","o":["Because only one right can exist at a time","Because rights are not valuable","Because sometimes rights conflict, for example the right to free expression and the right to privacy, and limits must be worked out","Because courts never deal with rights"],"a":[2]},{"id":"n11pt05-13","p":"n11pt05","n":13,"s":"pol","t":"Political Theory","q":"Which thinker's idea of human dignity held that people should be treated as ends in themselves, never only as means?","w":"Kant argued that every person has dignity and deserves respect. This idea underlies the modern view that rights protect each individual's dignity.","o":["Karl Marx","Thomas Hobbes","Immanuel Kant","Niccolò Machiavelli"],"a":[2]},{"id":"n11pt05-14","p":"n11pt05","n":14,"s":"pol","t":"Political Theory","q":"In recent years, new rights have been claimed and recognised, as discussed in the chapter. Which of the following is an example?","w":"As societies face new problems, people claim new rights. In India, laws on the right to information and court judgments on the environment show how the list of rights grows.","o":["The right of kings to rule","The right to own slaves","The right to ignore laws","Rights such as the right to information, or the right to clean air and water"],"a":[3]},{"id":"n11pt05-15","p":"n11pt05","n":15,"s":"pol","t":"Political Theory","q":"Why is it important that rights are recognised by the state, according to the chapter?","w":"When rights are in the constitution and laws, people can approach courts to protect them. Rights also tell the state what it must not do, limiting its power over citizens.","o":["Because legal recognition allows rights to be protected and enforced, while also restraining the state itself","Because the state can then abolish them easily","Because only the state can feel rights","Because rights do not need any protection"],"a":[0]},{"id":"n11pt05-16","p":"n11pt05","n":16,"s":"pol","t":"Political Theory","q":"Rights such as freedom of expression, freedom of religion and the right to a fair trial, which protect individuals against the state and others, are often called:","w":"Civil liberties protect individuals in their daily lives against arbitrary action. They support political rights by allowing people to discuss, organise and dissent freely.","o":["Economic entitlements","Civil liberties","Cultural traditions","Natural resources"],"a":[1]},{"id":"n11pt05-17","p":"n11pt05","n":17,"s":"pol","t":"Political Theory","q":"Which of the following claims would the chapter NOT treat as a right?","w":"A right must be important for human dignity or well-being and be justifiable to others. Wanting a brand of clothes is a preference, not a right.","o":["The claim to be educated","The claim to wear clothes of a particular brand","The claim to be free from torture","The claim to express one's views"],"a":[1]},{"id":"n11pt05-18","p":"n11pt05","n":18,"s":"pol","t":"Political Theory","q":"Which of the following is the main source of the idea of human rights today?","w":"Modern human rights rest on universal human dignity, not on nationality, caste, class or the goodwill of rulers.","o":["A belief that rights depend on a person's wealth","A belief that only governments can define what rights are","A belief that rights come from a ruler's kindness","The belief that every human being, by being human, deserves certain conditions to live with dignity"],"a":[3]},{"id":"n11pt05-19","p":"n11pt05","n":19,"s":"pol","t":"Political Theory","q":"Why does the chapter say rights are important in a democracy?","w":"Democracy is not only majority rule. Rights guarantee that even those who lose an election or belong to small groups keep their freedoms and dignity.","o":["Because they protect individuals and minorities from the tyranny of the majority and allow citizens to take part as equals","Because they allow the majority to do anything it wants","Because they remove the need for elections","Because they apply only to elected leaders"],"a":[0]},{"id":"n11pt05-20","p":"n11pt05","n":20,"s":"pol","t":"Political Theory","q":"The right to education shows how a claim can become a legal right. In India, free and compulsory education for children aged 6 to 14 became a Fundamental Right through:","w":"The 86th Amendment added Article 21A, and the Right to Education Act (2009) put it into effect. Education had earlier been only a Directive Principle.","o":["The 42nd Amendment, 1976","The 44th Amendment, 1978","The 86th Amendment, 2002","The 73rd Amendment, 1992"],"a":[2]},{"id":"n11pt06-1","p":"n11pt06","n":1,"s":"pol","t":"Political Theory","q":"The chapter defines citizenship as:","w":"Citizens have equal rights and duties in the political community. Citizenship also involves the relationships citizens have with one another and their shared participation in public life.","o":["Residence in a country for more than five years","Full and equal membership of a political community, with rights and obligations","Ownership of property in a country","Membership of a political party"],"a":[1]},{"id":"n11pt06-2","p":"n11pt06","n":2,"s":"pol","t":"Political Theory","q":"Which of the following struggles is mentioned in the chapter as a struggle for equal citizenship rights?","w":"The chapter mentions the French Revolution, the anti-apartheid struggle and the women's and Dalit movements as struggles for full and equal citizenship.","o":["The Olympic Games","The industrial revolution in Britain","The space race","The struggle against apartheid in South Africa and movements of women and Dalits in India"],"a":[3]},{"id":"n11pt06-3","p":"n11pt06","n":3,"s":"pol","t":"Political Theory","q":"The British sociologist T.H. Marshall, in Citizenship and Social Class (1950), saw citizenship as involving three kinds of rights. They are:","w":"Marshall traced how civil rights (like freedom of speech and property), political rights (like voting) and social rights (like education and welfare) were extended to citizens over time.","o":["Civil, political and social rights","Natural, legal and moral rights","Religious, cultural and linguistic rights","Property, inheritance and trade rights"],"a":[0]},{"id":"n11pt06-4","p":"n11pt06","n":4,"s":"pol","t":"Political Theory","q":"Which of the following is NOT a way of acquiring Indian citizenship under the Citizenship Act, 1955?","w":"Indian citizenship can be acquired by birth, descent, registration, naturalisation or the inclusion of territory into India. Political party membership has nothing to do with it.","o":["Birth","Descent","Paying a fee to a political party","Registration and naturalisation"],"a":[2]},{"id":"n11pt06-5","p":"n11pt06","n":5,"s":"pol","t":"Political Theory","q":"The provisions about citizenship in the Indian Constitution are found in:","w":"Part II (Articles 5 to 11) deals with citizenship at the commencement of the Constitution and gives Parliament the power to make laws on it, which it did through the Citizenship Act, 1955.","o":["Part II","Part III","Part IV","Part IXA"],"a":[0]},{"id":"n11pt06-6","p":"n11pt06","n":6,"s":"pol","t":"Political Theory","q":"Which of the following problems related to citizenship in cities is discussed in the chapter?","w":"The chapter points out that the urban poor contribute to the city's economy but often lack housing, water, sanitation and security, which raises the question of what equal citizenship requires for them.","o":["Too many parks","Excess of public transport","The difficulties of slum-dwellers and the urban poor in getting basic services and being treated as equal citizens","The lack of luxury goods"],"a":[2]},{"id":"n11pt06-7","p":"n11pt06","n":7,"s":"pol","t":"Political Theory","q":"Free movement and the right to settle anywhere in the country are rights of Indian citizens. These rights matter especially to:","w":"Migrants often face hostility from local groups claiming jobs for \"sons of the soil\". The chapter asks how equal citizenship can be ensured for people who move within the country.","o":["Foreign tourists","Diplomats","Only government employees","Migrant workers who move to other states and cities in search of work"],"a":[3]},{"id":"n11pt06-8","p":"n11pt06","n":8,"s":"pol","t":"Political Theory","q":"Rights of tribal people and forest dwellers to their lands and forests, discussed in the chapter, raise which question about citizenship?","w":"Equal citizenship does not always mean identical policies. Groups with special needs, like forest dwellers whose livelihood depends on forests, may need special protection.","o":["Whether they should be allowed to vote","How the needs and ways of life of different groups can be protected while treating all as equal citizens","Whether they should leave the country","Whether forests belong to foreign countries"],"a":[1]},{"id":"n11pt06-9","p":"n11pt06","n":9,"s":"pol","t":"Political Theory","q":"People who are forced to leave their country and have no state willing to accept them as citizens are called:","w":"Refugees and stateless people live without the protection that citizenship provides. The chapter uses their plight to show how important citizenship is.","o":["Diplomats","Stateless people or refugees","Migrant workers","Expatriates"],"a":[1]},{"id":"n11pt06-10","p":"n11pt06","n":10,"s":"pol","t":"Political Theory","q":"The idea of \"universal citizenship\" means that:","w":"Universal citizenship holds that every person living in a state should be able to enjoy full membership. In practice, rules about who is a citizen are often exclusive, which creates problems for minorities and migrants.","o":["All countries should merge into one","Every person should be a citizen of every country","Only rich countries should give citizenship","Full and equal membership should be available to all people within the nation-state, and no one should be left out"],"a":[3]},{"id":"n11pt06-11","p":"n11pt06","n":11,"s":"pol","t":"Political Theory","q":"The idea of \"global citizenship\", discussed in the chapter, is based on:","w":"Global citizenship is a sense of belonging to a world community. It can make it easier to address problems that cross borders, though it does not replace national citizenship.","o":["The view that we live in an interconnected world and share responsibilities for problems like human rights violations and environmental damage across borders","A single world government that has already been formed","Abolishing all national citizenships","Travelling abroad frequently"],"a":[0]},{"id":"n11pt06-12","p":"n11pt06","n":12,"s":"pol","t":"Political Theory","q":"Which of the following is generally considered an obligation of citizenship?","w":"Citizenship involves duties as well as rights: legal duties like paying taxes and moral obligations to respect others and take part in the community's shared life.","o":["Avoiding all participation in public life","Disobeying laws whenever one wishes","Respecting the rights of fellow citizens and taking part in the life of the community, such as paying taxes and obeying laws","Supporting only one political party"],"a":[2]},{"id":"n11pt06-13","p":"n11pt06","n":13,"s":"pol","t":"Political Theory","q":"Which of the following is an example of citizens claiming rights through peaceful protest, as described in the chapter?","w":"Struggles for citizenship have often taken the form of movements that demand equal rights and dignity for groups that were excluded.","o":["Organised violence against a minority","Bribing officials","Banning newspapers","Struggles like the women's movement and the Dalit movement to claim equal rights"],"a":[3]},{"id":"n11pt06-14","p":"n11pt06","n":14,"s":"pol","t":"Political Theory","q":"Equal citizenship, according to the chapter, implies that:","w":"Equal citizenship means equal rights and protections. Policies such as special help for the disadvantaged can be part of making that equality real.","o":["Citizens should get the same basic rights and protections from the state, whatever their caste, religion, gender or wealth","All citizens must have the same income","All citizens must speak one language","Citizens must belong to the same religion"],"a":[0]},{"id":"n11pt06-15","p":"n11pt06","n":15,"s":"pol","t":"Political Theory","q":"In the chapter's discussion of citizenship and nation, which statement is correct?","w":"Some countries define the nation by a shared history, religion or ethnicity; others in more inclusive, civic terms. These choices shape the rules for citizenship.","o":["All countries use exactly the same rules for granting citizenship","Countries define their national identity in different ways, and this affects who is easily accepted as a citizen","Citizenship has nothing to do with national identity","Only rich people can become citizens anywhere"],"a":[1]},{"id":"n11pt06-16","p":"n11pt06","n":16,"s":"pol","t":"Political Theory","q":"The Indian Constitution, according to the chapter, aimed at an inclusive idea of citizenship. Which provision reflects this?","w":"India's Constitution gives equal citizenship to all, with no religious or linguistic test. It also provides special protections for groups like SCs, STs and minorities.","o":["Citizenship only for people of one religion","A requirement to speak Hindi to be a citizen","Equal rights for all citizens without discrimination on grounds of religion, caste, sex or place of birth","Separate citizenship for each state"],"a":[2]},{"id":"n11pt06-17","p":"n11pt06","n":17,"s":"pol","t":"Political Theory","q":"Why does the chapter say that the right to free movement and settlement can lead to conflict?","w":"Such tensions show that equal citizenship has to be defended in practice. The state must protect migrants' rights while addressing the concerns of local people.","o":["Because people never move","Because the Constitution bans movement","Because local residents sometimes resent newcomers, especially when jobs and resources are scarce, and demand preference for \"sons of the soil\"","Because migrants cannot vote anywhere"],"a":[2]},{"id":"n11pt06-18","p":"n11pt06","n":18,"s":"pol","t":"Political Theory","q":"Which of these is an example of a social right in T.H. Marshall's sense?","w":"Social rights cover economic welfare and security, like education and health care. Freedom of speech is a civil right; voting and forming parties are political rights.","o":["Freedom of speech","The right to education and health care","The right to vote","The right to form a political party"],"a":[1]},{"id":"n11pt06-19","p":"n11pt06","n":19,"s":"pol","t":"Political Theory","q":"Which of the following best explains why citizenship is not only a legal status, according to the chapter?","w":"Citizens do not just hold rights; they take part in debates, movements and civic life, which is how the meaning of citizenship itself has expanded over time.","o":["Because it can be bought","Because only courts decide it","Because it lasts only for a short time","Because it also involves relationships between citizens and their active participation in shaping the community's life"],"a":[3]},{"id":"n11pt06-20","p":"n11pt06","n":20,"s":"pol","t":"Political Theory","q":"The French Revolution of 1789 is important in the history of citizenship because:","w":"The Revolution challenged the privileges of the monarchy and aristocracy and proclaimed the rights of man and the citizen, which inspired later struggles for equal citizenship.","o":["It asserted the idea that the people, as citizens, are sovereign and equal, ending the privileges of birth","It created a world government","It abolished all governments","It gave citizenship only to the nobility"],"a":[0]},{"id":"n11pt07-1","p":"n11pt07","n":1,"s":"pol","t":"Political Theory","q":"In nineteenth-century Europe, nationalism played a part in:","w":"Nationalism brought together small states into Germany and Italy, and in the early twentieth century it helped break up the Austro-Hungarian, Russian and Ottoman empires.","o":["Only the break-up of states","Only the unification of states","Ending all wars","Both the unification of smaller kingdoms into larger states, like Germany and Italy, and the break-up of large empires"],"a":[3]},{"id":"n11pt07-2","p":"n11pt07","n":2,"s":"pol","t":"Political Theory","q":"How does the chapter describe a nation?","w":"A nation is unlike a family or a club. Its members are bound by a sense of belonging built on shared beliefs, a common history and aspirations for a shared political future.","o":["A group of people related by blood, like a family","A community largely based on shared beliefs, history, territory and political ideals, whose members may never meet one another","Any group of people who speak the same language","An association like a club, formed by contract"],"a":[1]},{"id":"n11pt07-3","p":"n11pt07","n":3,"s":"pol","t":"Political Theory","q":"Which of the following does the chapter NOT treat as an essential basis of nationhood?","w":"The chapter argues that a nation does not need a single religion, race or language. Many nations, like India, include many religions and languages and are united by shared political ideals and history.","o":["Shared beliefs","Shared history","A single common religion","Shared political ideals"],"a":[2]},{"id":"n11pt07-4","p":"n11pt07","n":4,"s":"pol","t":"Political Theory","q":"The claim of a national group to govern itself and decide its own future is called:","w":"National self-determination is the demand that a nation should have its own state or self-government. After the First World War it was used to redraw the map of Europe.","o":["The right to national self-determination","The harm principle","Universal franchise","Proportional representation"],"a":[0]},{"id":"n11pt07-5","p":"n11pt07","n":5,"s":"pol","t":"Political Theory","q":"After the First World War, the idea of \"one culture, one state\" was used to redraw state boundaries in Europe. What problem did this create, according to the chapter?","w":"People of different cultures lived mixed together, so new borders left many as minorities in the new states. This caused tensions, migration and conflict.","o":["No state was ever formed","All states became very small islands","It was impossible to give every cultural group its own state, and new minorities were created within the new states","All minorities disappeared"],"a":[2]},{"id":"n11pt07-6","p":"n11pt07","n":6,"s":"pol","t":"Political Theory","q":"The chapter suggests that instead of creating a separate state for every cultural group, democracies should:","w":"The chapter favours pluralism: accommodating diversity through rights for minorities and federal arrangements, so that groups feel secure without breaking up states.","o":["Recognise and protect the rights and identities of minorities within existing states","Expel minorities","Ban all regional languages","Create one state for every language"],"a":[0]},{"id":"n11pt07-7","p":"n11pt07","n":7,"s":"pol","t":"Political Theory","q":"Which Indian poet and thinker criticised narrow nationalism, saying that patriotism cannot be our final spiritual shelter and that his refuge was humanity?","w":"Tagore opposed colonial rule but warned against a nationalism that hates other peoples. He valued the universal ideals of humanity above the nation.","o":["Mahatma Gandhi","Subhas Chandra Bose","Bal Gangadhar Tilak","Rabindranath Tagore"],"a":[3]},{"id":"n11pt07-8","p":"n11pt07","n":8,"s":"pol","t":"Political Theory","q":"Which statement about Tagore's views on nationalism is correct?","w":"Tagore believed India could learn from the West while resisting colonialism. He feared that aggressive nationalism would lead to hatred and violence.","o":["He supported British rule in India","He opposed colonial rule but criticised the kind of nationalism that rejects other cultures and glorifies the nation above humanity","He wanted India to conquer other countries","He was against any contact with Western ideas"],"a":[1]},{"id":"n11pt07-9","p":"n11pt07","n":9,"s":"pol","t":"Political Theory","q":"The chapter notes that nationalism has had both positive and negative effects. Which of the following is a negative effect it mentions?","w":"Nationalism inspired freedom struggles but has also been used to justify war and to suppress groups seen as outsiders.","o":["Bitter conflicts and wars, and the oppression of minorities in the name of the nation","The end of colonial rule","Unity among diverse people in a freedom struggle","The creation of democratic constitutions"],"a":[0]},{"id":"n11pt07-10","p":"n11pt07","n":10,"s":"pol","t":"Political Theory","q":"In Asia and Africa, nationalism was closely associated with:","w":"Anti-colonial movements in countries like India drew on nationalism to unite people against foreign rule and to claim self-government.","o":["The growth of monarchies","The spread of colonial empires","Struggles against colonial rule for independence","The rejection of all forms of statehood"],"a":[2]},{"id":"n11pt07-11","p":"n11pt07","n":11,"s":"pol","t":"Political Theory","q":"Why does the chapter say a nation is an \"imagined\" community?","w":"Imagined does not mean false. It means the bond among millions of people who never meet is built on shared ideas, stories and symbols.","o":["Because nations do not exist at all","Because members of a nation will never know most of their fellow members, yet they feel bound together by shared beliefs and aspirations","Because nations exist only in films","Because only poets belong to nations"],"a":[1]},{"id":"n11pt07-12","p":"n11pt07","n":12,"s":"pol","t":"Political Theory","q":"The chapter says that the territory a nation claims is important because:","w":"A homeland carries emotional meaning for a nation. Competing claims on the same territory are one reason for conflicts between nations.","o":["It is always very small","It has no value for national identity","It is fixed forever and cannot be disputed","Nations often see a particular territory as their homeland, tied to their history and memories"],"a":[3]},{"id":"n11pt07-13","p":"n11pt07","n":13,"s":"pol","t":"Political Theory","q":"What does the chapter mean by \"shared political ideals\" as a basis of nationhood?","w":"A nation can be bound by a shared vision of its political future. In India, commitment to democracy and the Constitution is part of what holds diverse people together.","o":["Everybody must vote for the same party","A common commitment to values such as democracy, secularism and liberalism, which members of a nation accept","Everybody must follow the same religion","Following the orders of one leader"],"a":[1]},{"id":"n11pt07-14","p":"n11pt07","n":14,"s":"pol","t":"Political Theory","q":"Which of the following best describes the Indian approach to national identity, as discussed in the chapter?","w":"India's national movement brought together people of different backgrounds. The Constitution protects diverse identities while building a common citizenship.","o":["One religion and one language for all","A nation for only the majority community","Abolition of all regional identities","Unity in diversity: a national identity that accommodates many religions, languages and regional identities"],"a":[3]},{"id":"n11pt07-15","p":"n11pt07","n":15,"s":"pol","t":"Political Theory","q":"\"Nationalism and pluralism\" in the chapter refers to the idea that:","w":"Pluralism means accepting many identities within one nation. Democracies try to accommodate them through rights for minorities and devolution of power.","o":["There must be one nationality in every state","Every group must form its own country","A nation can contain many cultural groups, whose rights and identities should be respected","Minorities should have no rights"],"a":[2]},{"id":"n11pt07-16","p":"n11pt07","n":16,"s":"pol","t":"Political Theory","q":"Why do many national groups that demand self-determination want their own state, according to the chapter?","w":"Groups who feel excluded or oppressed often see statehood as the only guarantee of their identity. The chapter argues that democracies can often address such fears through rights and autonomy.","o":["Because they feel their culture, rights and identity would be better protected under their own government","Because international law requires every group to have a state","Because they want to stop holding elections","Because they want to join an empire"],"a":[0]},{"id":"n11pt07-17","p":"n11pt07","n":17,"s":"pol","t":"Political Theory","q":"Which of the following empires broke up in the early twentieth century, partly due to nationalist movements?","w":"After the First World War, the Austro-Hungarian and Ottoman empires broke into several new states based on national identities. The Russian empire also collapsed in 1917.","o":["The Austro-Hungarian and Ottoman empires","The Mughal and Vijayanagara empires","The Roman and Persian empires","The Maurya and Gupta empires"],"a":[0]},{"id":"n11pt07-18","p":"n11pt07","n":18,"s":"pol","t":"Political Theory","q":"According to the chapter, national identity in a democracy should be:","w":"An inclusive national identity makes all citizens feel they belong. Excluding minorities from the idea of the nation creates insecurity and conflict.","o":["Based on loyalty to one religion","Fixed by the government and never questioned","Inclusive, recognising the equal rights of all members including minorities","Defined only by language"],"a":[2]},{"id":"n11pt07-19","p":"n11pt07","n":19,"s":"pol","t":"Political Theory","q":"Which of the following is an example of a national symbol that helps create a shared sense of belonging, as mentioned at the start of the chapter?","w":"Celebrations, anthems and flags build a shared identity. The chapter begins by noting how such occasions express nationalism.","o":["A private company logo","A local market","A shopping festival","The Republic Day parade and the national anthem"],"a":[3]},{"id":"n11pt07-20","p":"n11pt07","n":20,"s":"pol","t":"Political Theory","q":"Which of the following statements reflects the chapter's overall view of nationalism?","w":"The chapter asks students to recognise both sides: nationalism helped end colonial rule and unite people, but in narrow forms it has caused exclusion and violence.","o":["Nationalism is always harmful","Nationalism has inspired freedom and unity but can also lead to intolerance; a democratic nationalism respects diversity and minority rights","Nationalism has no place in modern politics","Nationalism requires that only one culture survive in a country"],"a":[1]},{"id":"n11pt08-1","p":"n11pt08","n":1,"s":"pol","t":"Political Theory","q":"According to the chapter, secularism is first of all a doctrine that opposes:","w":"Secularism is not anti-religion. It opposes domination of one religious group by another, and also domination within a religion, such as caste discrimination or the subordination of women.","o":["All religions and religious practice","Science and modern education","All forms of institutionalised religious domination, both between religions and within religions","The freedom to change one's religion"],"a":[2]},{"id":"n11pt08-2","p":"n11pt08","n":2,"s":"pol","t":"Political Theory","q":"Discrimination against Dalits within a religious community, or the denial of equal status to women within it, is an example of:","w":"Intra-religious domination happens inside a religion. Secularism challenges it too, which is why the Indian Constitution abolished untouchability.","o":["Intra-religious domination","Inter-religious domination","National self-determination","Proportional representation"],"a":[0]},{"id":"n11pt08-3","p":"n11pt08","n":3,"s":"pol","t":"Political Theory","q":"Which of the following is a feature of a secular state, as described in the chapter?","w":"A secular state keeps institutional separation from religion: no state religion and no rule by religious heads. Its aim is to promote peace, freedom and equality among and within religious groups.","o":["It is run by religious leaders","It does not establish any official religion and is not run by the heads of any religion","It bans all religious festivals","It supports only the majority religion"],"a":[1]},{"id":"n11pt08-4","p":"n11pt08","n":4,"s":"pol","t":"Political Theory","q":"The dominant Western (European) model of secularism, as described in the chapter, is based on:","w":"The Western model keeps a strict wall between state and religion. It focuses on individual freedom and equality between individuals, and pays little attention to the rights of communities.","o":["State intervention to reform religions","Financial support to all religions equally","Recognition of community rights for religious minorities","Mutual exclusion: the state does not interfere in religion and religion does not interfere in the affairs of the state"],"a":[3]},{"id":"n11pt08-5","p":"n11pt08","n":5,"s":"pol","t":"Political Theory","q":"Which of the following is a feature of Indian secularism that distinguishes it from the Western model?","w":"Indian secularism allows the state to engage with religion for equality and reform, and recognises the community rights of minorities, such as setting up their own educational institutions.","o":["The state never deals with any religious matter","Only individuals, not communities, have rights","Religious minorities have no special rights","The state can intervene in religion to reform practices like untouchability, and it can give aid to educational institutions run by religious communities"],"a":[3]},{"id":"n11pt08-6","p":"n11pt08","n":6,"s":"pol","t":"Political Theory","q":"The idea that the state keeps a \"principled distance\" from religion means that:","w":"Principled distance is not fixed separation. The state decides, on principle, when to stay out of religious matters and when to intervene, for example against untouchability or to secure equality for women.","o":["The state treats all religions with total indifference in every case","The state may keep away from or intervene in religion, depending on which approach better promotes freedom and equality","The state supports only one religion","The state bans all religious practice in public"],"a":[1]},{"id":"n11pt08-7","p":"n11pt08","n":7,"s":"pol","t":"Political Theory","q":"Which provision of the Indian Constitution is an example of state intervention in religion to end intra-religious domination?","w":"The Constitution abolished untouchability (Article 17) and allows laws throwing open Hindu religious institutions to all classes. This shows Indian secularism's concern for equality within religions.","o":["Abolition of untouchability","Freedom of the press","The office of the Vice-President","The Seventh Schedule"],"a":[0]},{"id":"n11pt08-8","p":"n11pt08","n":8,"s":"pol","t":"Political Theory","q":"In Turkey, Mustafa Kemal Ataturk followed a kind of secularism that:","w":"Ataturk aggressively pushed religion out of public life, banning the fez and changing the script. The chapter contrasts this with the Indian approach, which respects all religions.","o":["Encouraged religious leaders to run the state","Gave equal funds to all religions","Involved active state intervention against religion in public life, such as discouraging traditional dress and replacing the Arabic script","Was identical to the Indian model of secularism"],"a":[2]},{"id":"n11pt08-9","p":"n11pt08","n":9,"s":"pol","t":"Political Theory","q":"How did Jawaharlal Nehru understand secularism, according to the chapter?","w":"Nehru was not personally religious, but he did not oppose religion. For him secularism meant equal respect for all faiths and firm opposition to communalism of every kind.","o":["As hostility to all religions","As equal respect for all religions, complete opposition to communalism and a state that does not favour any religion","As support for the majority religion only","As a ban on religious education everywhere"],"a":[1]},{"id":"n11pt08-10","p":"n11pt08","n":10,"s":"pol","t":"Political Theory","q":"Which of the following criticisms of Indian secularism does the chapter discuss?","w":"The chapter examines these criticisms one by one and argues that Indian secularism is a distinct model suited to India's diversity, though it can be misused in practice.","o":["That it is too similar to the American model","That it ignores the Constitution","That it is anti-religious, a Western import, favours minorities, is too interventionist and encourages vote bank politics","That it bans elections"],"a":[2]},{"id":"n11pt08-11","p":"n11pt08","n":11,"s":"pol","t":"Political Theory","q":"Critics say that Indian secularism leads to \"vote bank politics\". What does this criticism mean?","w":"The chapter replies that seeking the support of groups is part of democratic politics; the problem arises only when leaders exploit such groups without serving their real interests.","o":["That banks fund elections","That secularism stops people from voting","That elections are held in banks","That politicians may use religious groups as blocks of voters, making promises to them for votes"],"a":[3]},{"id":"n11pt08-12","p":"n11pt08","n":12,"s":"pol","t":"Political Theory","q":"How does the chapter respond to the criticism that Indian secularism is a \"Western import\"?","w":"Indian secularism developed in response to the coexistence of many religions in India. Its concern for community rights and intra-religious equality makes it different from the Western model.","o":["It argues that Indian secularism grew out of India's own deep religious diversity and differs from the Western model in important ways","It agrees that it was copied from the West without change","It says secularism does not exist in India","It says secularism is only found in Europe"],"a":[0]},{"id":"n11pt08-13","p":"n11pt08","n":13,"s":"pol","t":"Political Theory","q":"Why does Indian secularism give importance to community-based rights, unlike the Western model?","w":"Equality for individuals in India often depends on the security of their communities. Hence the Constitution gives minorities the right to preserve their culture and run educational institutions.","o":["Because Indian communities have no individual members","Because the Constitution bans individual rights","Because in a diverse society, minority communities need protection of their culture and educational institutions to be truly equal","Because communities elect the President"],"a":[2]},{"id":"n11pt08-14","p":"n11pt08","n":14,"s":"pol","t":"Political Theory","q":"Which of the following is an example of inter-religious domination?","w":"Inter-religious domination means one religious group dominating or attacking another. Secularism aims to end both this and domination within religions.","o":["A religious community denying women the right to enter places of worship","Violence or discrimination by members of one religious community against those of another","Different caste groups within one religion","A person changing his or her own religion freely"],"a":[1]},{"id":"n11pt08-15","p":"n11pt08","n":15,"s":"pol","t":"Political Theory","q":"Critics argue that Indian secularism is \"interventionist\", since the state interferes in religious practices. What is the chapter's response?","w":"The state intervenes to protect rights, such as ending untouchability or ensuring equality for women. Such intervention is guided by constitutional values, not by hostility to religion.","o":["That intervention for reform and equality is consistent with principled distance and is aimed at freedom and equality, not domination","That the state never intervenes in any religion","That intervention is only allowed in favour of the majority","That intervention is banned by the Constitution"],"a":[0]},{"id":"n11pt08-16","p":"n11pt08","n":16,"s":"pol","t":"Political Theory","q":"Which statement about secularism and religion is correct, according to the chapter?","w":"Secularism opposes religious domination and discrimination, not faith itself. Many deeply religious people have defended secularism.","o":["A secular person must not believe in any religion","Secularism requires closing all places of worship","Secularism means the majority religion is the state religion","Secularism does not oppose religion; a person can be deeply religious and secular at the same time"],"a":[3]},{"id":"n11pt08-17","p":"n11pt08","n":17,"s":"pol","t":"Political Theory","q":"The Indian state's support to educational institutions run by religious minorities is consistent with secularism because:","w":"Aid given fairly, without favouring any religion, helps communities preserve their culture. This fits Indian secularism's idea of equal respect, not mutual exclusion.","o":["Secularism means favouring only minorities","Such support is given on a non-discriminatory basis and helps protect the community rights recognised by the Constitution","Secularism bans such institutions","Only the majority community can run schools"],"a":[1]},{"id":"n11pt08-18","p":"n11pt08","n":18,"s":"pol","t":"Political Theory","q":"Why does the chapter say that the Western model of mutual exclusion may not suit a society like India?","w":"Strict non-interference might leave practices like untouchability untouched. India's model allows the state to act against injustice while respecting all faiths.","o":["Because India has no religions","Because India's Constitution is unwritten","Because India has only one religion","Because religious diversity and deep social inequalities within religions in India may require the state to engage with religion to protect equality and freedom"],"a":[3]},{"id":"n11pt08-19","p":"n11pt08","n":19,"s":"pol","t":"Political Theory","q":"Which of the following best describes the aim of a secular state?","w":"A secular state protects individuals and communities from religious domination and ensures equal citizenship regardless of faith.","o":["To promote one religion over others","To ban public discussion of religion","To promote peace, freedom and equality among and within religious communities","To give religious leaders control of the courts"],"a":[2]},{"id":"n11pt08-20","p":"n11pt08","n":20,"s":"pol","t":"Political Theory","q":"The word \"secular\" was added to the Preamble of the Indian Constitution in 1976. Which statement about this is correct, according to the chapter's view?","w":"Fundamental Rights such as freedom of religion and equality before law already made the Constitution secular in content. The 42nd Amendment only added the word to the Preamble.","o":["The Constitution was secular in its provisions from the start; the amendment made the word explicit","Before 1976 India had a state religion","The word was later removed by the 44th Amendment","The amendment made India a religious state"],"a":[0]}],"instagram":"learn_with_anil06","exb":null,"site":"https://learnwithanil.in","notes":[],"wa":"919494792739","booksSoon":true,"mains":[],"mainsP5":null,"mainsLink":"","ranks":{"asof":"2026-11-08","site":[1,0,0,1,0,3,4,6,1,4,8,3,3,5,2,4,3,2,4,2,0],"exam":null,"tests":{}},"notesTitle":"","notesLede":"","key":"ncert-11","exam":"NCERT Class 11","mockonly":false,"bahubali":"","examShort":"NCERT Class 11","papersNote":"One set of MCQs for every chapter of the NCERT Class 11 textbooks, written by Learn with Anil, with answers and explanations. Chapters are added every week.","hub":false,"board":"NCERT","l2":{"code":"hi","label":"हिंदी","name":"Hindi","font":"Noto Sans Devanagari"},"base":"ncert-class-11/","qotd":[],"pay":{"on":true,"api":"https://script.google.com/macros/s/AKfycbxgNi2CfnbaEsVpA1Ghgy0AdYdUG7eYBkol5zqcbMgA2Q4D0Pvy0rndLxeyE7MlPy_3Rg/exec","exam":"ncert-class-11","freePyq":false,"gid":"644036954959-a75a02tj491g95pmddmbdvv074227ms9.apps.googleusercontent.com","ref":true,"otp":false,"prog":true,"pyq":{"price":149,"valid":"valid for 12 months from the day you pay, on every exam","exams":"APPSC Group 2, APPSC Group 1, UPSC CAPF AC, UPSC EPFO, UPSC Prelims, SSC CGL, RRB NTPC, RRB Group D, SSC GD Constable, SSC MTS, TS Police SI, TS Police Constable, TGPSC Group 1, TGPSC Group 2, TGPSC HMWSSB Manager, APPSC AMVI, TGPSC AMVI, APPSC EO Grade 3, APPSC Analyst Grade 2, APPSC Assistant Environmental Engineer, APPSC ASO, AP DSC, APPSC FRO, AP Police SI, AP Police Constable, RPF SI, RPF Constable, TNPSC Group 4, KEA FDA SDA, GPSTR, MPSC Group C, GSSSB CCE, UPSSSC Inter Level Mains, UPPSC RO ARO, UKPSC Lower PCS, CG Vyapam, OPSC ASO, WBPSC IDO, DSSSB, SBI PO, IBPS SO, NCERT Class 11, NCERT Class 12","trial":0},"mock":null,"combo":null,"pages":{"pyq":"/ncert-class-11/pyqs.html","mock":"/ncert-class-11/mock-test.html","sec":"/ncert-class-11/sectional-tests.html"},"sample":10},"exams":[],"cats":[],"timers":[],"pb":"/ncert-class-11/","qpages":true,"examSeo":"NCERT Class 11","homeTitle":"NCERT Class 11 MCQs Chapter-wise with Answers – Polity, History, Geography, Economics, Sociology, Art & Science | Learn with Anil","hubTitle":"Learn with Anil (LearnWithAnil.in) – PYQs with Answers: UPSC Prelims, Mains & Anthropology, APPSC Group 1 & 2, TS Police, SSC CGL"};
